class CreditsDialog(tk.Toplevel):
    """Parse tab's "Credits" button - a simple list of who contributed
    what, see the module-level CREDITS list."""
    def __init__(self, parent):
        super().__init__(parent)
        self.title("Credits")
        self.resizable(False, False)
        self.grab_set()

        ttk.Label(self, text="Credits", font=('Arial', 13, 'bold')).pack(anchor='w', padx=16, pady=(14,8))

        rows_frame = ttk.Frame(self)
        rows_frame.pack(padx=16, pady=(0,4))
        for row, (name, role) in enumerate(CREDITS):
            ttk.Label(rows_frame, text=name, font=('Arial', 10, 'bold')).grid(
                row=row, column=0, sticky='w', padx=(0,12), pady=3)
            ttk.Label(rows_frame, text=role).grid(row=row, column=1, sticky='w', pady=3)

        ttk.Button(self, text="Close", command=self.destroy).pack(pady=(10,14))


class ItemMatchDialog(tk.Toplevel):
    """Modal dialog listing close-spelling matches for a searched item name,
    letting the user confirm which one they actually meant."""
    def __init__(self, parent, query: str, matches: list):
        super().__init__(parent)
        self.result = None
        self.title("Did you mean...?")
        self.resizable(False, False)
        self.grab_set()

        ttk.Label(self, text=f"No exact match for '{query}'. Closest matches:",
                 font=('Arial', 9)).pack(anchor='w', padx=10, pady=(10,4))

        self.listbox = tk.Listbox(self, height=min(6, len(matches)), width=50)
        for m in matches:
            self.listbox.insert(tk.END, m)
        self.listbox.selection_set(0)
        self.listbox.pack(padx=10, pady=4)

        bf = ttk.Frame(self)
        bf.pack(pady=10)
        ttk.Button(bf, text="Use Selected", command=self._confirm).pack(side='left', padx=8)
        ttk.Button(bf, text="Cancel", command=self.destroy).pack(side='left', padx=8)

    def _confirm(self):
        sel = self.listbox.curselection()
        if sel:
            self.result = self.listbox.get(sel[0])
        self.destroy()


class FieldEditorDialog(tk.Toplevel):
    """Modal dialog to add or edit a single field."""
    def __init__(self, parent, mode: str, existing: dict = None):
        super().__init__(parent)
        self.result = None
        self.mode = mode
        source_opts = {'chat': CHAT_SOURCES, 'combat': COMBAT_SOURCES, 'loot': LOOT_SOURCES,
                       'xp': XP_SOURCES, 'damage': DAMAGE_SOURCES,
                       'pvp_dealt': PVP_SOURCES, 'pvp_taken': PVP_SOURCES}[mode]

        self.title("Edit Field" if existing else "Add Field")
        self.resizable(False, False)
        self.grab_set()

        pad = {'padx': 10, 'pady': 6}

        ttk.Label(self, text="Column label (header text):").grid(row=0, column=0, sticky='w', **pad)
        self.lbl_var = tk.StringVar(value=existing['label'] if existing else '')
        ttk.Entry(self, textvariable=self.lbl_var, width=26).grid(row=0, column=1, **pad)

        ttk.Label(self, text="Data source:").grid(row=1, column=0, sticky='w', **pad)
        self.src_var = tk.StringVar(value=existing['source_key'] if existing else source_opts[0])
        ttk.Combobox(self, textvariable=self.src_var, values=source_opts,
                     state='readonly', width=24).grid(row=1, column=1, **pad)

        ttk.Label(self, text="Column position (1=A, 2=B…):").grid(row=2, column=0, sticky='w', **pad)
        self.col_var = tk.IntVar(value=existing['col'] if existing else 1)
        ttk.Spinbox(self, textvariable=self.col_var, from_=1, to=30,
                    width=6).grid(row=2, column=1, sticky='w', **pad)

        bf = ttk.Frame(self)
        bf.grid(row=3, column=0, columnspan=2, pady=10)
        ttk.Button(bf, text="Save", command=self._save).pack(side='left', padx=8)
        ttk.Button(bf, text="Cancel", command=self.destroy).pack(side='left', padx=8)

    def _save(self):
        lbl = self.lbl_var.get().strip()
        if not lbl:
            messagebox.showwarning("Missing", "Enter a label.", parent=self)
            return
        self.result = {'label': lbl, 'source_key': self.src_var.get(), 'col': self.col_var.get()}
        self.destroy()


class SnapshotViewer(tk.Toplevel):
    """Shows the raw parsed rows for one sheet type so user can verify."""
    def __init__(self, parent, title: str, rows: list, fields: list):
        super().__init__(parent)
        self.title(f"Snapshot — {title}  ({len(rows)} rows)")
        self.geometry("1100x540")

        if not rows:
            ttk.Label(self, text="No data parsed yet.  Run Parse first.",
                      font=('Arial', 12)).pack(expand=True)
            return

        cols = [f['label'] for f in fields]
        keys = [f['source_key'] for f in fields]

        frame = ttk.Frame(self)
        frame.pack(fill='both', expand=True)

        tv = ttk.Treeview(frame, columns=cols, show='headings', height=22)
        for c in cols:
            tv.heading(c, text=c, command=lambda c=c: _sort_treeview_column(tv, c, False))
            tv.column(c, width=max(80, len(c) * 9), stretch=True)

        vsb = ttk.Scrollbar(frame, orient='vertical',   command=tv.yview)
        hsb = ttk.Scrollbar(frame, orient='horizontal', command=tv.xview)
        tv.configure(yscrollcommand=vsb.set, xscrollcommand=hsb.set)

        tv.grid(row=0, column=0, sticky='nsew')
        vsb.grid(row=0, column=1, sticky='ns')
        hsb.grid(row=1, column=0, sticky='ew')
        frame.rowconfigure(0, weight=1)
        frame.columnconfigure(0, weight=1)

        for row in rows[:2000]:
            tv.insert('', 'end', values=[str(row.get(k, '')) for k in keys])

        ttk.Label(self, text=f"Showing up to 2 000 of {len(rows)} rows",
                  foreground='gray').pack(pady=4)


class LogSearchViewer(tk.Toplevel):
    """Shows every raw log line matching a search term, across all loaded
    files. Right-click a row for "Open Log at This Line" - opens the
    original file in a LogFileViewer, scrolled to and highlighting that
    exact line."""
    def __init__(self, parent, query: str, results: list):
        super().__init__(parent)
        self.title(f"Search Results — '{query}'  ({len(results)} matches)")
        self.geometry("1150x540")
        # iid -> (file_name, path, line_num), for the right-click handler -
        # path isn't a displayed column, so it isn't visible in `values`.
        self._row_source = {}

        cols = ('File', 'Line #', 'Timestamp', 'Text')
        frame = ttk.Frame(self)
        frame.pack(fill='both', expand=True)

        tv = ttk.Treeview(frame, columns=cols, show='headings', height=22)
        widths = {'File': 220, 'Line #': 70, 'Timestamp': 90, 'Text': 700}
        for c in cols:
            tv.heading(c, text=c, command=lambda c=c: _sort_treeview_column(tv, c, False))
            tv.column(c, width=widths[c], anchor='center' if c == 'Line #' else 'w')

        vsb = ttk.Scrollbar(frame, orient='vertical',   command=tv.yview)
        hsb = ttk.Scrollbar(frame, orient='horizontal', command=tv.xview)
        tv.configure(yscrollcommand=vsb.set, xscrollcommand=hsb.set)

        tv.grid(row=0, column=0, sticky='nsew')
        vsb.grid(row=0, column=1, sticky='ns')
        hsb.grid(row=1, column=0, sticky='ew')
        frame.rowconfigure(0, weight=1)
        frame.columnconfigure(0, weight=1)

        for i, (file_name, line_num, timestamp, text, path) in enumerate(results[:5000]):
            iid = str(i)
            tv.insert('', 'end', iid=iid, values=(file_name, line_num, timestamp, text))
            self._row_source[iid] = (file_name, path, line_num)

        shown = min(len(results), 5000)
        ttk.Label(self, text=f"Showing {shown} of {len(results)} matching lines",
                  foreground='gray').pack(pady=4)

        self.tv = tv
        _attach_open_log_menu(tv, self._row_source, self)


class DropSnapshotViewer(tk.Toplevel):
    """Lists every drop event found for an item; selecting one shows a
    snapshot of the raw log from the last timestamp through that drop
    line. Right-click a row for "Open Log at This Line" - opens the
    original file in a LogFileViewer, scrolled to and highlighting the
    exact drop line, for more surrounding context than the snapshot pane."""
    def __init__(self, parent, query: str, drops: list):
        super().__init__(parent)
        self.title(f"Drop Search — '{query}'  ({len(drops)} drops)")
        self.geometry("1150x650")
        self.drops = drops

        paned = ttk.PanedWindow(self, orient='vertical')
        paned.pack(fill='both', expand=True)

        list_frame = ttk.Frame(paned)
        paned.add(list_frame, weight=1)

        cols = ('File', 'Timestamp', 'Item', 'Mob')
        self.tv = ttk.Treeview(list_frame, columns=cols, show='headings', height=12)
        widths = {'File': 220, 'Timestamp': 90, 'Item': 320, 'Mob': 220}
        for c in cols:
            self.tv.heading(c, text=c, command=lambda c=c: _sort_treeview_column(self.tv, c, False))
            self.tv.column(c, width=widths[c], anchor='center' if c == 'Timestamp' else 'w')

        vsb = ttk.Scrollbar(list_frame, orient='vertical', command=self.tv.yview)
        self.tv.configure(yscrollcommand=vsb.set)
        self.tv.pack(side='left', fill='both', expand=True)
        vsb.pack(side='right', fill='y')

        for i, d in enumerate(drops):
            self.tv.insert('', 'end', iid=str(i),
                           values=(d['file'], d['timestamp'], d['item'], d['mob']))
        self.tv.bind('<<TreeviewSelect>>', self._on_select)

        row_source = {str(i): (d['file'], d['path'], d['line_num']) for i, d in enumerate(drops)}
        _attach_open_log_menu(self.tv, row_source, self)

        snapshot_frame = ttk.LabelFrame(paned, text="Snapshot (last timestamp → drop)", padding=6)
        paned.add(snapshot_frame, weight=1)

        self.snapshot_text = tk.Text(snapshot_frame, wrap='none', height=10, state='disabled')
        snap_vsb = ttk.Scrollbar(snapshot_frame, orient='vertical', command=self.snapshot_text.yview)
        snap_hsb = ttk.Scrollbar(snapshot_frame, orient='horizontal', command=self.snapshot_text.xview)
        self.snapshot_text.configure(yscrollcommand=snap_vsb.set, xscrollcommand=snap_hsb.set)
        self.snapshot_text.grid(row=0, column=0, sticky='nsew')
        snap_vsb.grid(row=0, column=1, sticky='ns')
        snap_hsb.grid(row=1, column=0, sticky='ew')
        snapshot_frame.rowconfigure(0, weight=1)
        snapshot_frame.columnconfigure(0, weight=1)

        ttk.Label(self, text=f"{len(drops)} drop(s) found — select a row above to view its snapshot",
                  foreground='gray').pack(pady=4)

        if drops:
            self.tv.selection_set('0')
            self._on_select()

    def _on_select(self, event=None):
        sel = self.tv.selection()
        if not sel:
            return
        drop = self.drops[int(sel[0])]
        self.snapshot_text.config(state='normal')
        self.snapshot_text.delete('1.0', tk.END)
        self.snapshot_text.insert('1.0', drop['snapshot'])
        self.snapshot_text.config(state='disabled')


def _attach_open_log_menu(tv, row_source, dialog_parent):
    """Wires up the standard "Open Log at This Line" right-click action on
    any Treeview whose rows each correspond to one specific log file line -
    right-clicking anywhere on a row opens that file in a LogFileViewer,
    scrolled to and highlighting the exact line. A default for every chart/
    table in the app built from one-row-per-log-line data - just build
    row_source (a dict of {iid: (file_name, path, line_num)}, one entry per
    row actually inserted into tv) and call this once afterward. Shared by
    LogSearchViewer, DropSnapshotViewer, PvpResultViewer, and the Parse
    tab's XP Counter/Damage Counter reports.

    dialog_parent is whatever LogFileViewer should be a child of - the
    Toplevel itself for a standalone results window, or the main App
    instance for a report embedded directly in a tab (XP/Damage Counter)."""
    menu = tk.Menu(tv, tearoff=0)

    def _open_selected():
        sel = tv.selection()
        if not sel:
            return
        entry = row_source.get(sel[0])
        if not entry:
            return
        file_name, path, line_num = entry
        if not path:
            return
        LogFileViewer(dialog_parent, file_name, path, line_num)

    menu.add_command(label="Open Log at This Line", command=_open_selected)

    def _on_right_click(event):
        row_iid = tv.identify_row(event.y)
        if not row_iid:
            return
        tv.selection_set(row_iid)
        menu.tk_popup(event.x_root, event.y_root)

    tv.bind('<Button-3>', _on_right_click)
    return menu


class LogFileViewer(tk.Toplevel):
    """Opens one log file's full raw content in a scrollable, read-only
    view, highlighting and scrolling to one specific line - the "Open Log
    at This Line" right-click action on a search/drop result row, so a
    match can be seen in its complete original context (not just the short
    snapshot/single line already shown in the results table itself). A
    search box at the top (with Next/Previous arrows, or plain Enter/
    Shift+Enter) lets you then look around the rest of the file."""
    def __init__(self, parent, file_name, file_path, line_num):
        super().__init__(parent)
        self.title(f"Log — {file_name} (line {line_num})")
        self.geometry("1000x650")
        self._last_match_start = None
        self._last_match_end = None

        search_row = ttk.Frame(self)
        search_row.pack(fill='x', padx=6, pady=6)
        ttk.Label(search_row, text="Find:").pack(side='left')
        self.search_var = tk.StringVar(value='')
        search_entry = ttk.Entry(search_row, textvariable=self.search_var, width=40)
        search_entry.pack(side='left', padx=4)
        search_entry.bind('<Return>', lambda e: self._find_next())
        search_entry.bind('<Shift-Return>', lambda e: self._find_previous())
        ttk.Button(search_row, text="▲", width=3,
                  command=self._find_previous).pack(side='left', padx=(4,0))
        ttk.Button(search_row, text="▼", width=3,
                  command=self._find_next).pack(side='left', padx=(2,0))
        self.search_status = ttk.Label(search_row, text="", foreground='gray')
        self.search_status.pack(side='left', padx=8)

        frame = ttk.Frame(self)
        frame.pack(fill='both', expand=True)

        text = tk.Text(frame, wrap='none', font=('Consolas', 10))
        self.text = text
        vsb = ttk.Scrollbar(frame, orient='vertical', command=text.yview)
        hsb = ttk.Scrollbar(frame, orient='horizontal', command=text.xview)
        text.configure(yscrollcommand=vsb.set, xscrollcommand=hsb.set)
        text.grid(row=0, column=0, sticky='nsew')
        vsb.grid(row=0, column=1, sticky='ns')
        hsb.grid(row=1, column=0, sticky='ew')
        frame.rowconfigure(0, weight=1)
        frame.columnconfigure(0, weight=1)

        try:
            with open(file_path, 'r', encoding='utf-8', errors='ignore') as fh:
                content = fh.read()
        except Exception as e:
            text.insert('1.0', f"Could not open file:\n{file_path}\n\n{e}")
            text.config(state='disabled')
            return

        text.insert('1.0', content)
        text.tag_configure('highlight', background='#fff59d')
        # A different color from 'highlight' above (the originally-opened
        # target line) so a search match is never confused with it.
        text.tag_configure('search_match', background='#ffb74d')
        line_start = f"{line_num}.0"
        text.tag_add('highlight', line_start, f"{line_num}.end")
        text.config(state='disabled')

        # see() only guarantees the line is somewhere on screen (often right
        # at the bottom edge) - scrolling back up a bit after roughly
        # centers it instead, so there's context visible above it too.
        text.see(line_start)
        text.update_idletasks()
        text.yview_scroll(-15, 'units')

        ttk.Label(self, text=file_path, foreground='gray').pack(anchor='w', padx=6, pady=(0,4))
        search_entry.focus_set()

    def _find_next(self):
        self._search(forward=True)

    def _find_previous(self):
        self._search(forward=False)

    def _search(self, forward):
        """Finds the next/previous case-insensitive match of the search
        box's text, starting just past the last match (or from the very
        start/end of the file if there's no match yet), wrapping around
        if it runs off the corresponding end without finding anything."""
        term = self.search_var.get()
        text = self.text
        text.tag_remove('search_match', '1.0', 'end')
        if not term:
            self.search_status.config(text="")
            return

        if forward:
            start = self._last_match_end or '1.0'
            idx = text.search(term, start, stopindex='end', nocase=True)
            if not idx:
                idx = text.search(term, '1.0', stopindex='end', nocase=True)
        else:
            start = self._last_match_start or 'end'
            idx = text.search(term, start, stopindex='1.0', backwards=True, nocase=True)
            if not idx:
                idx = text.search(term, 'end', stopindex='1.0', backwards=True, nocase=True)

        if not idx:
            self._last_match_start = None
            self._last_match_end = None
            self.search_status.config(text="No matches")
            return

        end_idx = f"{idx}+{len(term)}c"
        text.tag_add('search_match', idx, end_idx)
        text.see(idx)
        self._last_match_start = idx
        self._last_match_end = end_idx
        self.search_status.config(text="")


class PvpResultViewer(tk.Toplevel):
    """Shared viewer for every PvP search (see App._find_pvp_deaths,
    _find_pvp_kills, _find_pvp_participated) - each row is the matched
    trigger line, labeled per the search kind. Right-click a row for "Open
    Log at This Line", same as LogSearchViewer/DropSnapshotViewer.
    player_name is optional - Participated has no player name of its own
    (see _search_pvp_participated), so an empty string omits that part of
    the title instead of showing an empty pair of quotes."""
    def __init__(self, parent, window_title, player_name, results: list, line_col_label, found_word):
        super().__init__(parent)
        if player_name:
            self.title(f"{window_title} — '{player_name}'  ({len(results)} found)")
        else:
            self.title(f"{window_title}  ({len(results)} found)")
        self.geometry("1150x540")
        self.results = results

        cols = ('File', 'Line #', 'Timestamp', 'Label', line_col_label)
        frame = ttk.Frame(self)
        frame.pack(fill='both', expand=True)

        tv = ttk.Treeview(frame, columns=cols, show='headings', height=22)
        widths = {'File': 200, 'Line #': 70, 'Timestamp': 90, 'Label': 160, line_col_label: 480}
        for c in cols:
            tv.heading(c, text=c, command=lambda c=c: _sort_treeview_column(tv, c, False))
            tv.column(c, width=widths[c], anchor='center' if c == 'Line #' else 'w')

        vsb = ttk.Scrollbar(frame, orient='vertical', command=tv.yview)
        hsb = ttk.Scrollbar(frame, orient='horizontal', command=tv.xview)
        tv.configure(yscrollcommand=vsb.set, xscrollcommand=hsb.set)
        tv.grid(row=0, column=0, sticky='nsew')
        vsb.grid(row=0, column=1, sticky='ns')
        hsb.grid(row=1, column=0, sticky='ew')
        frame.rowconfigure(0, weight=1)
        frame.columnconfigure(0, weight=1)

        for i, r in enumerate(results):
            tv.insert('', 'end', iid=str(i),
                      values=(r['file'], r['line_num'], r['timestamp'], r['label'], r['match_line']))

        ttk.Label(self, text=f"{len(results)} {found_word} found",
                  foreground='gray').pack(pady=4)

        self.tv = tv
        row_source = {str(i): (r['file'], r['path'], r['line_num']) for i, r in enumerate(results)}
        _attach_open_log_menu(tv, row_source, self)


def _patch_widgets_for_debug_logging():
    """Wraps every ttk.Button/ttk.Checkbutton's own `command=` callback
    (module-wide, one-time) so each click logs what was clicked and any
    exception it raised to the debug console, before/around calling the
    real callback unchanged - covers the vast majority of "commands" a
    user actually issues without needing to hand-instrument every one of
    the hundreds of individual button/checkbox call sites throughout this
    file. Idempotent (checked via a marker attribute) since App() could
    in principle be constructed more than once in a process.

    Right-click context menus (tk.Menu.add_command/add_checkbutton) are a
    separate mechanism entirely from a Button's own `command=` - e.g. the
    Results tab's per-row "Rebuild (Saved Items First)"/"Remove from
    Build" menu items - and need their own wrap alongside the widget one
    above, or a whole class of real user actions (anything reached via a
    right-click menu) would go completely unlogged."""
    if getattr(ttk.Button, '_olmran_debug_patched', False):
        return
    for widget_cls in (ttk.Button, ttk.Checkbutton):
        orig_init = widget_cls.__init__

        def patched_init(self, master=None, _orig_init=orig_init, **kwargs):
            cmd = kwargs.get('command')
            if callable(cmd):
                label = kwargs.get('text') or (cmd.__name__ if hasattr(cmd, '__name__') else '')

                def wrapped(*args, _cmd=cmd, _label=label):
                    _debug_log(f'Clicked: {_label!r}')
                    try:
                        return _cmd(*args)
                    except Exception:
                        _debug_log('EXCEPTION in click handler:\n' + traceback.format_exc())
                        raise
                kwargs['command'] = wrapped
            _orig_init(self, master, **kwargs)
        widget_cls.__init__ = patched_init
    ttk.Button._olmran_debug_patched = True

    for method_name in ('add_command', 'add_checkbutton', 'add_radiobutton'):
        orig_method = getattr(tk.Menu, method_name)

        def patched_menu_method(self, _orig_method=orig_method, **kwargs):
            cmd = kwargs.get('command')
            if callable(cmd):
                label = kwargs.get('label') or (cmd.__name__ if hasattr(cmd, '__name__') else '')

                def wrapped(*args, _cmd=cmd, _label=label):
                    _debug_log(f'Menu item clicked: {_label!r}')
                    try:
                        return _cmd(*args)
                    except Exception:
                        _debug_log('EXCEPTION in menu item handler:\n' + traceback.format_exc())
                        raise
                kwargs['command'] = wrapped
            return _orig_method(self, **kwargs)
        setattr(tk.Menu, method_name, patched_menu_method)


class App(tk.Tk):
    def __init__(self):
        super().__init__()
        # OLMRAN_HEADLESS_TEST is set only by the scratchpad regression
        # scripts (never by a real user, and never by the TEST BUILD exe
        # itself - that one only sets OLMRAN_TEST_CONFIG, which stays
        # visible on purpose) - withdrawing THIS early, before any of
        # _build_ui's widget construction below, means the window is
        # never actually mapped/shown at all, instead of being visible
        # for the second or so construction takes and only hidden
        # afterward (which is what every regression script's own
        # app.withdraw() call - still there, now redundant but harmless -
        # was doing). Real users and the real TEST BUILD never set this,
        # so this has zero effect on anything they see.
        if os.environ.get('OLMRAN_HEADLESS_TEST'):
            self.withdraw()
        if _DEBUG_CONSOLE_ENABLED:
            _start_debug_console()
            _patch_widgets_for_debug_logging()
            # Tkinter's own hook, called automatically for an uncaught
            # exception raised inside ANY callback/binding/after() call -
            # broader coverage than the Button/Checkbutton wrap above
            # alone (catches Treeview bindings, Combobox selection
            # events, trace_add callbacks, etc. too). Still runs the
            # default behavior (prints to stderr) via the base class
            # implementation, so nothing about normal error handling
            # changes outside this debug build - this only adds the
            # extra copy into the debug console.
            _default_report_callback_exception = self.report_callback_exception
            def _debug_report_callback_exception(exc, val, tb):
                _debug_log('UNCAUGHT EXCEPTION:\n' + ''.join(traceback.format_exception(exc, val, tb)))
                _default_report_callback_exception(exc, val, tb)
            self.report_callback_exception = _debug_report_callback_exception
        # OLMRAN_TEST_CONFIG lets a separate local-only test build (see
        # test_launcher.py, never committed/pushed) point at an isolated
        # config file instead of the real one, and hard-clean it on every
        # launch - so pre-release testing always starts from scratch
        # without ever touching a real user's saved data. Unset for every
        # normal build/user, so this is a no-op outside that test flow.
        is_test_build = bool(os.environ.get('OLMRAN_TEST_CONFIG'))
        self.is_test_build = is_test_build
        title_suffix = " [TEST BUILD]" if is_test_build else ""
        self.title(f"🎮 Olmran Log Parser and Gear Set Creator v{VERSION}{title_suffix}")
        # Bank Build's Saved Items (per-character tabs, Only Found In,
        # Prioritize/Hard Search/Search-all-characters, etc.) needs more
        # vertical space than the old 815px default fit - tall enough that
        # the shared Min/Max/Specific Level + search buttons under the Build
        # tab were cut off below the visible window on first launch. Width
        # 1425 (measured from the running exe, resized to comfortably fit
        # Manual tab's 3-tab Gear Constraints mini-notebook); height 859 -
        # the user's own resized default as of v6.6.0 (measured live via
        # GetClientRect against the running exe, matching Tkinter's own
        # geometry() convention of client-area size, not outer window size).
        self.geometry("1425x859")
        self.minsize(1150, 750)
        self.resizable(True, True)
        self._set_app_icon()

        self.files: list[dict] = []       # {path, name, size, type}
        self.parsed = {'chat': [], 'combat': [], 'loot': [],
                       'xp': [], 'damage': [], 'pvp_dealt': [], 'pvp_taken': []}
        self.fields = {k: [dict(f) for f in v] for k, v in DEFAULT_FIELDS.items()}
        # Real values are set later (Build tab's own setup, then
        # _auto_load_community_list) - defaulted this early so anything
        # touching them during _build_ui (e.g. the Item Counter's own
        # startup auto-restore of a persisted "Consistent" tally - see
        # _build_parse_tab) has something safe to read before then.
        self.master_data = []
        self.blocked_area_items = []

        # Config file for persistent settings
        self.config_file = (os.environ.get('OLMRAN_TEST_CONFIG')
                           or os.path.join(os.path.expanduser("~"), ".gaming_log_parser_config.json"))

        # Load saved directories or use home as default
        self._load_config()

        # Suppressed until startup is fully done building/restoring every
        # tab's own live state from the _persisted_* values _load_config
        # just set - some tabs built early (e.g. the Item Counter's
        # "Consistent" tally auto-restore in _build_parse_tab, see
        # _open_item_counter's silent=True path) trigger a _save_config()
        # of their own as a side effect, which used to fire before later
        # tabs (Build tab's characters/Lockers, Saved Builds) had copied
        # their own _persisted_* data into live attributes yet - silently
        # overwriting bank_characters/saved_builds/locker_groups/etc. on
        # disk with still-empty defaults on every single launch. See
        # _save_config's own guard check.
        self._suppress_config_saves = True
        self._build_ui()

        # Auto-load the bundled community equipment list on startup, if present
        self._auto_load_community_list()
        self._suppress_config_saves = False

        # Save config on close
        self.protocol("WM_DELETE_WINDOW", self._on_closing)

        # Windows + the 'clam' theme sometimes leave stale/garbled pixels
        # behind on custom-drawn ttk widgets (e.g. Radiobutton glyphs) when
        # the window is maximized/restored, because Tk's damage-region
        # tracking doesn't always invalidate the whole client area on that
        # kind of native resize. Force a full repaint on any zoomed<->normal
        # state change via a near-invisible alpha nudge, which makes DWM
        # recomposite the whole window without actually resizing it.
        self._last_wm_state = self.state()
        self.bind('<Configure>', self._on_root_configure)

    def _on_root_configure(self, event):
        if event.widget is not self:
            return
        try:
            current_state = self.state()
        except tk.TclError:
            return
        if current_state != self._last_wm_state:
            self._last_wm_state = current_state
            self.after(50, self._force_full_redraw)
            if current_state == 'normal':
                self.after(50, self._clamp_to_workarea)

    def _clamp_to_workarea(self):
        """Restoring from maximized can leave the window positioned with
        its bottom edge at the monitor's full pixel height rather than
        its taskbar-adjusted work area - e.g. a 1920x1080 display with a
        48px taskbar has a work area only 1032px tall, but Windows was
        observed restoring this window to y=205 with an unchanged height
        of 875, landing its bottom edge at 1080 - 48px of it permanently
        hidden behind the taskbar, unreachable by any amount of internal
        scrolling since the clipped strip is OUTSIDE the window itself.
        Every tab is affected equally since it's the whole window that's
        misplaced, not any one tab's content - matches reports of "every
        tab clips, but only when not maximized". Coincides with adding
        per-monitor DPI awareness (see main()) - Windows stops silently
        correcting window placement for DPI-aware processes, so an app
        has to do this itself. Only called right after a zoomed->normal
        transition (see _on_root_configure) - a plain user resize/drag
        already keeps the window on-screen on its own."""
        if sys.platform != 'win32':
            return
        try:
            hwnd = self.winfo_id()
            MONITOR_DEFAULTTONEAREST = 2
            monitor = ctypes.windll.user32.MonitorFromWindow(hwnd, MONITOR_DEFAULTTONEAREST)

            class RECT(ctypes.Structure):
                _fields_ = [("left", ctypes.c_long), ("top", ctypes.c_long),
                           ("right", ctypes.c_long), ("bottom", ctypes.c_long)]

            class MONITORINFO(ctypes.Structure):
                _fields_ = [("cbSize", ctypes.c_ulong), ("rcMonitor", RECT),
                           ("rcWork", RECT), ("dwFlags", ctypes.c_ulong)]

            info = MONITORINFO()
            info.cbSize = ctypes.sizeof(MONITORINFO)
            ctypes.windll.user32.GetMonitorInfoW(monitor, ctypes.byref(info))
            work = info.rcWork
            work_w, work_h = work.right - work.left, work.bottom - work.top
            x, y = self.winfo_x(), self.winfo_y()
            w, h = self.winfo_width(), self.winfo_height()
            new_w, new_h = min(w, work_w), min(h, work_h)
            new_x = min(max(x, work.left), work.right - new_w)
            new_y = min(max(y, work.top), work.bottom - new_h)
            if (new_x, new_y, new_w, new_h) != (x, y, w, h):
                self.geometry(f"{new_w}x{new_h}+{new_x}+{new_y}")
        except Exception:
            pass

    def _force_full_redraw(self):
        try:
            self.attributes('-alpha', 0.999)
            self.after(10, lambda: self.attributes('-alpha', 1.0))
        except tk.TclError:
            pass
    
    def _load_config(self):
        """Load saved configuration from file"""
        try:
            if os.path.exists(self.config_file):
                with open(self.config_file, 'r') as f:
                    config = json.load(f)
                    self.last_open_dir = config.get('last_open_dir', os.path.expanduser("~"))
                    self.last_save_dir = config.get('last_save_dir', os.path.expanduser("~"))
                    self.armor_defaults = config.get('armor_defaults', {})
                    self.weapon_combo_defaults = config.get('weapon_combo_defaults', {})
                    # Raw data only (no tk.StringVar yet - the Saved Builds tab
                    # isn't built until later in __init__) - _build_saved_builds_tab
                    # turns this into self.saved_builds.
                    self._persisted_saved_builds = config.get('saved_builds', [])
                    self._persisted_saved_build_counter = config.get('saved_build_counter', 0)
                    # Bank Build's Saved Items tab - raw data only (Bank
                    # Build's sub-notebook isn't built until later in
                    # __init__); turned into self.bank_saved_sources/
                    # bank_saved_order in _build_build_tab.
                    self._persisted_bank_saved_sources = config.get('bank_saved_sources', {})
                    self._persisted_bank_saved_order = config.get('bank_saved_order', [])
                    # Bank Build's Import tab / per-character Saved Items -
                    # same deal, turned into self.bank_characters in
                    # _build_build_tab.
                    self._persisted_bank_characters = config.get('bank_characters', {})
                    # Saved Items' Gear Tag column - one tag per item name,
                    # shared across the Main tab and every character.
                    self._persisted_bank_gear_tags = config.get('bank_gear_tags', {})
                    # Share/Trade flags - kept separately from
                    # self.bank_characters (character_name -> set of item
                    # names) rather than inside each character's own cdata,
                    # so Clear Saved List/Delete Character/a fresh re-Import
                    # under the same name never loses them - the whole point
                    # being nobody has to re-flag a big list of items after
                    # any of that. See _toggle_shared_item/_toggle_trade_item.
                    self._persisted_bank_shared_items = config.get('bank_shared_items', {})
                    self._persisted_bank_trade_items = config.get('bank_trade_items', {})
                    # Named, full snapshots of every Basic/Armor/Weapon
                    # Constraints selection (Basic Constraints tab's "Save
                    # Constraints" button) - real app, persists for every
                    # user, not just test builds.
                    self._persisted_constraint_sets = config.get('constraint_sets', [])
                    # Basic Constraints' current selections (Wanted Spells,
                    # Priority Spells/Tier, Wanted Sigils, Required Items,
                    # Level filters) - TEST BUILD ONLY (see self.is_test_build).
                    # The real app never writes or reads this key at all, so
                    # a normal user's config file never gains it - see
                    # test_launcher.py, which no longer wipes this file
                    # between launches specifically so this (and Saved
                    # Items/characters, already persisted either way) keeps
                    # whatever was last set up as a fast-testing default.
                    self._persisted_test_basic_constraints = (
                        config.get('test_basic_constraints', {}) if self.is_test_build else {})
                    # Parse tab's XP Counter - saved area/hour reports (raw
                    # data only; turned into self.xp_saved_reports, complete
                    # with their tab frames, once the Parse tab is built).
                    self._persisted_xp_reports = config.get('xp_reports', [])
                    # Parse tab's Damage Counter - saved per-mob damage
                    # reports, same pattern as xp_reports above.
                    self._persisted_damage_reports = config.get('damage_reports', [])
                    # Parse tab's PvP Damage Counter - saved dealt/taken
                    # damage reports, same pattern as damage_reports above.
                    self._persisted_pvp_damage_reports = config.get('pvp_damage_reports', [])
                    # Parse tab's Item Counter - saved drop-rate reports,
                    # same pattern as damage_reports above.
                    self._persisted_item_reports = config.get('item_reports', [])
                    # Item Counter's "Consistent" checkbox - one running
                    # tally per character (see _compute_item_drop_stats/
                    # _extract_log_character/_item_tally_from_json), keyed
                    # by whatever character name each log's own filename
                    # carries ('Unknown' for files that don't fit that
                    # pattern) - not tied to any particular saved/working
                    # tab.
                    self.item_consistent_tally_by_character = {
                        char: self._item_tally_from_json(raw)
                        for char, raw in config.get('item_consistent_tally_by_character', {}).items()
                    }
                    # Item Counter's Character dropdown selection - applied
                    # to the StringVar once it's created in _build_parse_tab.
                    self._persisted_item_counter_character = config.get(
                        'item_counter_character', 'All Characters')
                    # Counters sub-tab's resizable "Load Log Files" table -
                    # last row count the user dragged it to (see
                    # _build_file_list_section's resizable=True path).
                    self._persisted_counters_file_rows = config.get(
                        'counters_file_list_rows', COUNTERS_FILE_LIST_DEFAULT_ROWS)
                    # Lockers' "+" tab Locker Groups - raw {'id','name'}
                    # pairs only, turned into real notebooks (each its own
                    # tab of self.bank_lockers_sub_notebook) in
                    # _build_build_tab, before individual character tabs
                    # are (re)created so a Locker's group_id has somewhere
                    # to land immediately.
                    self._persisted_locker_groups = config.get('locker_groups', [])
                    self._persisted_locker_group_counter = config.get('locker_group_counter', 0)
            else:
                self.last_open_dir = os.path.expanduser("~")
                self.last_save_dir = os.path.expanduser("~")
                self.armor_defaults = {}
                self.weapon_combo_defaults = {}
                self._persisted_saved_builds = []
                self._persisted_saved_build_counter = 0
                self._persisted_bank_saved_sources = {}
                self._persisted_bank_saved_order = []
                self._persisted_bank_characters = {}
                self._persisted_bank_gear_tags = {}
                self._persisted_bank_shared_items = {}
                self._persisted_bank_trade_items = {}
                self._persisted_constraint_sets = []
                self._persisted_test_basic_constraints = {}
                self._persisted_xp_reports = []
                self._persisted_damage_reports = []
                self._persisted_pvp_damage_reports = []
                self._persisted_item_reports = []
                self.item_consistent_tally_by_character = {}
                self._persisted_item_counter_character = 'All Characters'
                self._persisted_counters_file_rows = COUNTERS_FILE_LIST_DEFAULT_ROWS
                self._persisted_locker_groups = []
                self._persisted_locker_group_counter = 0
        except Exception:
            self.last_open_dir = os.path.expanduser("~")
            self.last_save_dir = os.path.expanduser("~")
            self.armor_defaults = {}
            self.weapon_combo_defaults = {}
            self._persisted_saved_builds = []
            self._persisted_saved_build_counter = 0
            self._persisted_bank_saved_sources = {}
            self._persisted_bank_saved_order = []
            self._persisted_bank_characters = {}
            self._persisted_bank_gear_tags = {}
            self._persisted_bank_shared_items = {}
            self._persisted_bank_trade_items = {}
            self._persisted_constraint_sets = []
            self._persisted_test_basic_constraints = {}
            self._persisted_xp_reports = []
            self._persisted_damage_reports = []
            self._persisted_pvp_damage_reports = []
            self._persisted_item_reports = []
            self.item_consistent_tally_by_character = {}
            self._persisted_item_counter_character = 'All Characters'
            self._persisted_counters_file_rows = COUNTERS_FILE_LIST_DEFAULT_ROWS
            self._persisted_locker_groups = []
            self._persisted_locker_group_counter = 0

    def _save_config(self):
        """Save configuration to file"""
        # Startup (see __init__'s _suppress_config_saves) can trigger this
        # as a side effect of an early tab restoring its own state (e.g.
        # the Item Counter's "Consistent" tally auto-restore) before later
        # tabs have copied their own persisted data into live attributes -
        # writing now would silently overwrite the real file with those
        # still-empty defaults. See __init__'s own comment for the incident
        # this fixed.
        if getattr(self, '_suppress_config_saves', False):
            return
        try:
            config = {
                'last_open_dir': self.last_open_dir,
                'last_save_dir': self.last_save_dir,
                'armor_defaults': getattr(self, 'armor_defaults', {}),
                'weapon_combo_defaults': getattr(self, 'weapon_combo_defaults', {}),
                'saved_builds': [
                    {'name': save['name'].get(), 'headers': list(save['headers']),
                     'rows': [list(row) for row in save['rows']]}
                    for save in getattr(self, 'saved_builds', [])
                ],
                'saved_build_counter': getattr(self, 'saved_build_counter', 0),
                'bank_saved_sources': {
                    src: dict(counts) for src, counts in getattr(self, 'bank_saved_sources', {}).items()
                },
                'bank_saved_order': list(getattr(self, 'bank_saved_order', [])),
                'bank_characters': {
                    char: {
                        'sources': {src: dict(counts) for src, counts in cdata['sources'].items()},
                        'order': list(cdata['order']),
                        'is_locker': bool(cdata.get('is_locker', False)),
                        'exclude_from_others': bool(cdata.get('exclude_from_others', False)),
                        'group_id': cdata.get('group_id'),
                        'enchants': dict(cdata.get('enchants', {})),
                    }
                    for char, cdata in getattr(self, 'bank_characters', {}).items()
                },
                'bank_gear_tags': dict(getattr(self, 'bank_gear_tags', {})),
                # Kept by character NAME rather than inside bank_characters'
                # own per-character dict, specifically so Clear Saved List/
                # Delete Character/a fresh re-Import never loses them - see
                # _toggle_shared_item/_toggle_trade_item's docstrings.
                'bank_shared_items': {
                    char: sorted(names) for char, names in getattr(self, 'bank_shared_items_by_char', {}).items()
                },
                'bank_trade_items': {
                    char: sorted(names) for char, names in getattr(self, 'bank_trade_items_by_char', {}).items()
                },
                'locker_groups': [
                    {'id': g['id'], 'name': g['name']}
                    for g in getattr(self, 'bank_locker_groups', [])
                ],
                'locker_group_counter': getattr(self, 'bank_locker_group_counter', 0),
                'constraint_sets': [
                    {'name': cs['name'], 'data': cs['data']}
                    for cs in getattr(self, 'saved_constraint_sets', [])
                ],
                'xp_reports': [
                    {'name': rep['name'], 'data': rep['data']}
                    for rep in getattr(self, 'xp_saved_reports', [])
                ],
                'damage_reports': [
                    {'name': rep['name'], 'data': rep['data']}
                    for rep in getattr(self, 'damage_saved_reports', [])
                ],
                'pvp_damage_reports': [
                    {'name': rep['name'], 'data': rep['data']}
                    for rep in getattr(self, 'pvp_damage_saved_reports', [])
                ],
                'item_reports': [
                    {'name': rep['name'], 'data': rep['data']}
                    for rep in getattr(self, 'item_saved_reports', [])
                ],
                'item_consistent_tally_by_character': {
                    char: self._item_tally_to_json(raw)
                    for char, raw in getattr(self, 'item_consistent_tally_by_character', {}).items()
                },
                'item_counter_character': (self.item_counter_character.get()
                                          if hasattr(self, 'item_counter_character') else 'All Characters'),
                'counters_file_list_rows': getattr(
                    self, '_counters_file_rows', COUNTERS_FILE_LIST_DEFAULT_ROWS),
            }
            if getattr(self, 'is_test_build', False):
                # Basic Constraints' current selections - TEST BUILD ONLY,
                # never written to a real user's config file. Lets
                # test_launcher.py (which no longer wipes this file between
                # launches) keep whatever's currently set up as a fast-
                # testing default instead of starting from scratch.
                config['test_basic_constraints'] = {
                    'wanted_spells_data': list(getattr(self, 'wanted_spells_data', [])),
                    'priority_spells_data': list(getattr(self, 'priority_spells_data', [])),
                    'priority_tiers_data': [list(pair) for pair in getattr(self, 'priority_tiers_data', [])],
                    'wanted_sigils_data': list(getattr(self, 'wanted_sigils_data', [])),
                    'wanted_sigils_required': list(getattr(self, 'wanted_sigils_required', set())),
                    'wanted_sigils_protect_required': list(getattr(self, 'wanted_sigils_protect_required', set())),
                    'required_items': [dict(item) for item in getattr(self, 'required_items', [])],
                    'min_level': self.min_level_var.get() if hasattr(self, 'min_level_var') else '',
                    'max_level': self.max_level_var.get() if hasattr(self, 'max_level_var') else '',
                    'specific_level': self.specific_level_var.get() if hasattr(self, 'specific_level_var') else '',
                    'specific_level_fallback': (self.specific_level_fallback_var.get()
                                               if hasattr(self, 'specific_level_fallback_var') else 'none'),
                }
            with open(self.config_file, 'w') as f:
                json.dump(config, f)
        except Exception:
            pass  # Silently fail if can't save config

    def _restore_test_basic_constraints(self):
        """TEST BUILD ONLY - repopulates Basic Constraints (Wanted Spells,
        Priority Spells/Tier, Wanted Sigils, Required Items, Level filters)
        from whatever was last saved (see _save_config), so a fresh test
        launch starts from a known, fast-to-reach state instead of empty.
        Never runs outside a test build (see self.is_test_build) - a real
        user's config file never has this data in the first place."""
        data = getattr(self, '_persisted_test_basic_constraints', None) or {}
        if not data:
            return
        self.wanted_spells_data = list(data.get('wanted_spells_data', []))
        self.priority_spells_data = list(data.get('priority_spells_data', []))
        self.priority_tiers_data = [tuple(pair) for pair in data.get('priority_tiers_data', [])]
        self.wanted_sigils_data = list(data.get('wanted_sigils_data', []))
        self.wanted_sigils_required = set(data.get('wanted_sigils_required', []))
        self.wanted_sigils_protect_required = set(data.get('wanted_sigils_protect_required', []))
        self.required_items = [dict(item) for item in data.get('required_items', [])]
        self.min_level_var.set(data.get('min_level', ''))
        self.max_level_var.set(data.get('max_level', ''))
        self.specific_level_var.set(data.get('specific_level', ''))
        self.specific_level_fallback_var.set(data.get('specific_level_fallback', 'none'))
        self._render_spell_chips()
        self._render_priority_chips()
        self._render_wanted_sigil_chips()
        self._render_required_item_chips()

    def _on_closing(self):
        """Handle window closing"""
        self._save_config()
        self.destroy()

    # ── UPDATE CHECK / SELF-UPDATE ─────────────────────────────
    # Entirely manual - never runs on startup or on any timer, only when
    # the user clicks "Check for Update". Two separate steps: check (asks
    # GitHub's Releases API what the latest tag is, compares it to VERSION)
    # and, only if the user then clicks the resulting "Download & Update"
    # button, the actual download-and-replace (see _start_self_update).
    def _build_update_bar(self, nb):
        """"Download Page" and "Check for Update", side by side, with the
        check's status message underneath - placed (not packed) so it
        overlaps the Notebook's own tab strip at its top-right corner,
        landing in the same row as the top-level tabs (Parse/Fields/
        Export/...) instead of a separate row above them. Same horizontal
        position as before (anchored to the right edge) - only the
        vertical position moved. Still scrolls away with everything else
        (its parent is self._scroll_content, same as the Notebook itself -
        see _build_scrollable_root), it just visually rides along with
        wherever the tab strip currently is rather than being its own
        fixed-height row."""
        bar = ttk.Frame(self._scroll_content, padding=(8,0))

        button_row = ttk.Frame(bar)
        button_row.pack(side='top', anchor='e')
        ttk.Button(button_row, text="Download Page",
                  command=self._open_download_page).pack(side='left', padx=(0,8))
        self.update_check_button = ttk.Button(button_row, text="Check for Update",
                                              command=self._check_for_update)
        self.update_check_button.pack(side='left')

        # Not packed by default - only shown (see _set_update_status) while
        # there's actual status text, so the bar's background is normally
        # just as tall as the button row itself and never reaches down far
        # enough to cover the Notebook's own border line below the tab
        # strip it's overlapping.
        self.update_status_label = ttk.Label(bar, text="", foreground='#666')

        bar.place(in_=nb, relx=1.0, x=-4, y=-10, anchor='ne')

        self._pending_update_url = None
        self._pending_update_version = None

    def _set_update_status(self, text, foreground='#666'):
        """Sets the update-check status message, showing/hiding the label
        itself based on whether there's actually anything to say - see
        the comment where it's created (_build_update_bar) for why this
        matters (keeps the overlapping button bar's own background from
        growing tall enough to cover the border line below it)."""
        self.update_status_label.config(text=text, foreground=foreground)
        if text:
            self.update_status_label.pack(side='top', anchor='e', pady=(2,0))
        else:
            self.update_status_label.pack_forget()

    def _open_download_page(self):
        """"Download Page" button - opens the project's GitHub Pages
        download site in the default browser, for anyone who'd rather
        download and install a new version manually instead of using
        Check for Update's self-updater."""
        webbrowser.open("https://gnawbie.github.io/Olmran-parser-ItemBuilder/")

    @staticmethod
    def _version_tuple(v):
        parts = []
        for p in (v or '').strip().lstrip('vV').split('.'):
            try:
                parts.append(int(p))
            except ValueError:
                parts.append(0)
        return tuple(parts)

    def _check_for_update(self):
        """"Check for Update" button - disables itself and shows
        "Checking..." while a background thread asks GitHub's Releases API
        for the latest tag (see _check_for_update_worker), so the UI never
        freezes waiting on the network."""
        self.update_check_button.config(state='disabled', text="Checking...")
        self._set_update_status("")
        threading.Thread(target=self._check_for_update_worker, daemon=True).start()

    def _check_for_update_worker(self):
        """Runs off the main thread - only ever touches Tkinter widgets via
        self.after(0, ...), since Tkinter itself isn't thread-safe. Looks
        for a .zip asset (the Folder build) or a .exe asset (the onefile
        build) depending on which flavor is currently running (see
        _is_folder_build) - a release missing the matching asset (e.g. an
        older release cut before the Folder build existed) is reported the
        same as no update being available yet, via download_url being
        None."""
        _debug_log(f'Update check: starting (current version={VERSION}, folder_build={_is_folder_build()})')
        try:
            req = urllib.request.Request(
                f"https://api.github.com/repos/{GITHUB_REPO}/releases/latest",
                headers={'Accept': 'application/vnd.github+json',
                         'User-Agent': 'OlmranItemBuilder-UpdateCheck'})
            with urllib.request.urlopen(req, timeout=10) as resp:
                data = json.loads(resp.read().decode('utf-8'))
            latest_version = (data.get('tag_name') or '').strip()
            assets = data.get('assets') or []
            wanted_suffix = '.zip' if _is_folder_build() else '.exe'
            update_asset = next((a for a in assets
                              if (a.get('name') or '').lower().endswith(wanted_suffix)), None)
            download_url = update_asset.get('browser_download_url') if update_asset else None
            expected_size = update_asset.get('size') if update_asset else None
            _debug_log(f'Update check: latest tag={latest_version!r}, wanted asset suffix={wanted_suffix!r}, '
                       f'matching asset={(update_asset or {}).get("name")!r}, size={expected_size!r}')
            self.after(0, lambda: self._on_update_check_done(latest_version, download_url, expected_size, None))
        except Exception as e:
            _debug_log(f'Update check FAILED: {e!r}\n{traceback.format_exc()}')
            self.after(0, lambda: self._on_update_check_done(None, None, None, e))

    def _on_update_check_done(self, latest_version, download_url, expected_size, error):
        if error is not None or not latest_version:
            _debug_log(f'Update check done: check failed (error={error!r})')
            self.update_check_button.config(state='normal', text="Check for Update")
            self._set_update_status("Check failed - no internet?", foreground='#a33')
            return

        if self._version_tuple(latest_version) > self._version_tuple(VERSION):
            if not download_url:
                # A newer tag exists but has no .exe asset attached yet
                # (release still being prepared) - nothing to offer yet.
                _debug_log(f'Update check done: v{latest_version} exists but no matching asset attached yet')
                self.update_check_button.config(state='normal', text="Check for Update")
                self._set_update_status(
                    f"v{latest_version.lstrip('vV')} is out, but no download is attached yet",
                    foreground='#a33')
                return
            self._pending_update_url = download_url
            self._pending_update_size = expected_size
            self._pending_update_version = latest_version.lstrip('vV')
            _debug_log(f'Update check done: v{self._pending_update_version} available '
                       f'(url={download_url}, size={expected_size})')
            self.update_check_button.config(
                state='normal', text=f"⬇ Download & Update to v{self._pending_update_version}",
                command=self._start_self_update)
            self._set_update_status("")
        else:
            _debug_log(f'Update check done: already on latest version ({VERSION})')
            self.update_check_button.config(state='normal', text="Check for Update")
            self._set_update_status("You're on the latest version", foreground='#2a2')

    def _start_self_update(self):
        """"Download & Update" button (only shown once a newer version was
        found) - confirms with the user (this replaces the running exe, an
        action with no undo), then downloads the new exe and hands off to
        a small batch script (see _write_update_batch_script) that waits
        for this process to actually exit, swaps the new exe into place,
        and relaunches it. Only meaningful when actually running as the
        packaged .exe - from source (python gaming_log_parser.py) there's
        no exe for this to replace, so it just points at the release page
        instead."""
        # Not caught by the generic button-click log wrap - this button's
        # command is reassigned later via .config(command=...) once an
        # update is found, not set at __init__ time, so it never goes
        # through the wrapped constructor _patch_widgets_for_debug_logging
        # patches.
        _debug_log("Clicked: 'Download & Update' (Check for Update button, post-check state)")
        if not getattr(sys, 'frozen', False):
            _debug_log('Self-update: not running as a frozen exe, pointing at release page instead')
            messagebox.showinfo("Running From Source",
                "Self-update only applies to the packaged .exe. Since this is running from source, "
                "pull the latest changes from GitHub instead.")
            return

        version = self._pending_update_version
        confirmed = messagebox.askyesno("Download and Install Update",
                f"Download v{version} and install it?\n\n"
                "The app will close to install the update - you'll need to open it "
                "again yourself afterward to finish.")
        _debug_log(f'Self-update: confirm dialog for v{version} -> {"yes" if confirmed else "no"}')
        if not confirmed:
            return

        self.update_check_button.config(state='disabled', text="Downloading...")
        self._set_update_status("")
        threading.Thread(target=self._download_update_worker,
                         args=(self._pending_update_url, version, self._pending_update_size),
                         daemon=True).start()

    def _download_update_worker(self, download_url, version, expected_size):
        is_folder = _is_folder_build()
        _debug_log(f'Download worker: starting for v{version} (folder_build={is_folder}, '
                   f'url={download_url}, expected_size={expected_size})')
        try:
            current_exe = os.path.abspath(sys.executable)
            temp_dir = tempfile.gettempdir()

            req = urllib.request.Request(
                download_url, headers={'User-Agent': 'OlmranItemBuilder-UpdateCheck'})
            with urllib.request.urlopen(req, timeout=60) as resp:
                downloaded = resp.read()
            _debug_log(f'Download worker: downloaded {len(downloaded):,} bytes '
                       f'(first 2 bytes={downloaded[:2]!r})')

            # A truncated/interrupted download (connection dropped
            # partway through) can still land well above the old ">1MB"
            # floor and still be many MB short of the real thing - writing
            # that (or extracting it) over the working install produces a
            # corrupted install that fails to launch at all ("Failed to
            # load Python DLL"). Check against GitHub's own reported asset
            # size (exact byte count) when available, and always check
            # the file's own header magic bytes, so a bad download is
            # caught and reported here instead of ever touching the
            # installed copy.
            if expected_size and len(downloaded) != expected_size:
                raise ValueError(
                    f"Download incomplete - got {len(downloaded):,} bytes, expected {expected_size:,}. "
                    "Try again.")

            if is_folder:
                if len(downloaded) < 1_000_000 or downloaded[:2] != b'PK':
                    raise ValueError(
                        f"Downloaded file ({len(downloaded):,} bytes) doesn't look like a real zip. Try again.")

                new_zip_path = os.path.join(temp_dir, f"OlmranItemBuilder_Folder_v{version}.zip")
                with open(new_zip_path, 'wb') as f:
                    f.write(downloaded)

                # Extract now, on this still-running process, into a fresh
                # staging folder well away from the actual install - the
                # currently-running exe/_internal aren't touched by this,
                # so there's no conflict with the app still being open.
                # The batch script (see _finish_self_update) only has to
                # move already-extracted files into place, not run any
                # unzip step itself (cmd has no native unzip, and adding a
                # dependency on PowerShell's Expand-Archive there would be
                # one more thing that could go wrong per-machine).
                staging_dir = tempfile.mkdtemp(prefix="OlmranUpdateStaging_")
                with zipfile.ZipFile(new_zip_path) as zf:
                    zf.extractall(staging_dir)

                # A zip of the dist/OlmranItemBuilder folder extracts to
                # either that folder directly at the top level, or (if it
                # was zipped from one level up) a single top-level
                # subfolder wrapping it - handle both so how the zip
                # happened to get built doesn't matter.
                staged_exe = os.path.join(staging_dir, "OlmranItemBuilder.exe")
                staged_internal = os.path.join(staging_dir, "_internal")
                if not (os.path.isfile(staged_exe) and os.path.isdir(staged_internal)):
                    entries = [e for e in os.listdir(staging_dir)
                               if os.path.isdir(os.path.join(staging_dir, e))]
                    if len(entries) == 1:
                        inner = os.path.join(staging_dir, entries[0])
                        if (os.path.isfile(os.path.join(inner, "OlmranItemBuilder.exe"))
                                and os.path.isdir(os.path.join(inner, "_internal"))):
                            staging_dir = inner
                            staged_exe = os.path.join(staging_dir, "OlmranItemBuilder.exe")
                            staged_internal = os.path.join(staging_dir, "_internal")
                if not (os.path.isfile(staged_exe) and os.path.isdir(staged_internal)):
                    raise ValueError("Downloaded update zip doesn't have the expected folder layout.")

                _debug_log(f'Download worker: zip verified and extracted to {staging_dir}, '
                           f'handing off to _finish_self_update (is_folder=True)')
                self.after(0, lambda: self._finish_self_update(
                    current_exe, staged_exe, len(downloaded), is_folder=True,
                    staging_dir=staging_dir, downloaded_zip_path=new_zip_path))
            else:
                if len(downloaded) < 1_000_000 or downloaded[:2] != b'MZ':
                    raise ValueError(
                        f"Downloaded file ({len(downloaded):,} bytes) doesn't look like a real exe. Try again.")

                new_exe_path = os.path.join(temp_dir, f"OlmranItemBuilder_v{version}.exe")
                with open(new_exe_path, 'wb') as f:
                    f.write(downloaded)

                _debug_log(f'Download worker: exe verified and saved to {new_exe_path}, '
                           f'handing off to _finish_self_update (is_folder=False)')
                self.after(0, lambda: self._finish_self_update(current_exe, new_exe_path, len(downloaded)))
        except Exception as e:
            _debug_log(f'Download worker FAILED: {e!r}\n{traceback.format_exc()}')
            self.after(0, lambda: self._on_update_download_failed(e))

    def _on_update_download_failed(self, error):
        _debug_log(f'Update download failed, shown to user: {error}')
        self.update_check_button.config(
            state='normal', text=f"⬇ Download & Update to v{self._pending_update_version}",
            command=self._start_self_update)
        self._set_update_status(f"Download failed: {error}", foreground='#a33')

    def _finish_self_update(self, current_exe, new_exe_path, expected_size,
                             is_folder=False, staging_dir=None, downloaded_zip_path=None):
        """Hands off to a batch script that swaps the downloaded update
        into place, relaunches current_exe, and deletes itself - needed
        because a running Windows exe can't overwrite its own file (or,
        for the Folder build, its own loaded DLLs sitting in _internal).

        For the onefile build (is_folder=False, the original behavior):
        repeatedly tries to move new_exe_path over current_exe. A `move`
        onto a still-open exe fails with "Access is denied", so simply
        retrying the move doubles as the wait for this process to
        actually exit - no separate tasklist-based PID check needed
        (tried that; `tasklist | find` silently fails to match under a
        hidden/no-console batch process, some console-encoding quirk - it
        reported the PID gone immediately even while still running). Also
        re-checks new_exe_path's on-disk size against expected_size (the
        exact byte count already confirmed right after downloading)
        immediately before every move attempt - antivirus can quarantine
        or truncate a freshly-downloaded, unsigned exe sitting in Temp
        between when it was written and when this script finally gets
        around to moving it (it can only run once the old exe's process
        has fully exited, which isn't necessarily instant), and that gap
        was a real hole: the original per-download check only ran once,
        in memory, long before this.

        For the Folder build (is_folder=True): staging_dir/new_exe_path
        already hold a complete, already-extracted new install (done in
        Python by _download_update_worker, before this method was even
        called - cmd has no native unzip, so extraction happens once,
        up front, rather than adding a PowerShell dependency here).
        Renaming the OLD _internal folder to a backup name is used as the
        same "is anything still locked" probe the onefile path uses
        renaming the exe for - it can only succeed once every DLL loaded
        out of it has actually been released, which the exe's own file
        lock alone wouldn't guarantee. The new _internal is then moved
        into place, the backup deleted, and the exe itself overwritten
        the same way the onefile path does. If the swap fails partway
        (renamed old _internal out, but couldn't move the new one in),
        the backup is renamed straight back so the existing install is
        never left half-updated.

        Relaunches current_exe either way, even if the swap ultimately
        never succeeds, so the app never just vanishes - and never
        corrupts the existing install with a since-tampered download.
        Uses `ping` against loopback for retry delays instead of
        `timeout`, since `timeout` also misbehaves (returns instantly)
        without a real attached console.

        Runs in two modes, chosen by whether the current Windows account
        is this developer's own (see `verbose` below) - a real, visible
        console that stays open under the user's own control (ending in
        `pause`, only deleting itself after that keypress) ONLY on that
        one account, to actually watch what's happening live while
        chasing a recurring "Failed to load Python DLL" report. Everyone
        else keeps the original silent behavior: hidden window, output
        quietly appended to olmran_update_log.txt, auto-closes when done.
        Then exits immediately (os._exit, not a normal close) so the file
        lock is released right away instead of waiting on any further
        cleanup."""
        # Shown and dismissed BEFORE the batch script is even generated/
        # spawned, not after - the script's own move-retry loop only
        # allows a limited number of attempts (~60, a minute or so) while
        # waiting for this process to actually exit and release its file
        # lock. Showing this afterward let that clock start ticking
        # immediately while the user was still reading/deciding on the
        # dialog, and taking too long to click OK could burn through the
        # whole retry budget before this process ever exited - the swap
        # would then give up and the update would silently never
        # actually install. Blocking here first means current_exe's lock
        # only gets released a moment after the user clicks OK, right as
        # the script is about to start looking for it.
        messagebox.showinfo("Downloaded",
            "The update has finished downloading.\n\nClick OK to close the app and install it, then open it again yourself to continue.")
        # This developer's own machine only - see the module docstring
        # above for why this stays this narrow rather than applying to
        # every user.
        verbose = os.environ.get('USERNAME', '').strip().lower() == 'walli'
        try:
            bat_path = os.path.join(tempfile.gettempdir(), "olmran_update.bat")
            log_path = os.path.join(tempfile.gettempdir(), "olmran_update_log.txt")

            def emit(msg):
                return f'echo {msg}\r\n' if verbose else f'echo {msg} >> "{log_path}"\r\n'

            redirect = '' if verbose else f' >> "{log_path}" 2>&1'

            lines = ["@echo off\r\n"]
            if verbose:
                lines += [
                    'echo ============================================================\r\n',
                    'echo  Olmran Item Builder - installing update\r\n',
                    'echo  This window shows every step live and stays open until you\r\n',
                    'echo  close it - please leave it open until it says "finished".\r\n',
                    'echo ============================================================\r\n',
                    'echo.\r\n',
                ]
            else:
                lines += [f'echo [%date% %time%] starting move-retry loop > "{log_path}"\r\n']

            if is_folder:
                install_dir = os.path.dirname(current_exe)
                old_internal = os.path.join(install_dir, "_internal")
                old_internal_bak = os.path.join(install_dir, "_internal_old")
                staged_internal = os.path.join(staging_dir, "_internal")
                lines += [
                    "set retries=0\r\n",
                    ":retry_swap\r\n",
                    f'ren "{old_internal}" "_internal_old"{redirect}\r\n',
                    "if errorlevel 1 (\r\n",
                    "    set /a retries+=1\r\n",
                    emit('[%date% %time%] still in use, attempt %retries%'),
                    "    if %retries% GEQ 60 (\r\n",
                    emit('[%date% %time%] giving up - never unlocked, relaunching old install unchanged'),
                    "        goto relaunch\r\n",
                    "    )\r\n",
                    "    ping -n 2 127.0.0.1 >NUL\r\n",
                    "    goto retry_swap\r\n",
                    ")\r\n",
                    emit('[%date% %time%] old install unlocked, swapping in the update'),
                    f'move /y "{staged_internal}" "{old_internal}"{redirect}\r\n',
                    "if errorlevel 1 (\r\n",
                    emit('[%date% %time%] swap failed, restoring the previous install unchanged'),
                    f'    ren "{old_internal_bak}" "_internal"{redirect}\r\n',
                    "    goto relaunch\r\n",
                    ")\r\n",
                    f'rd /s /q "{old_internal_bak}" 2>NUL\r\n',
                    f'move /y "{new_exe_path}" "{current_exe}"{redirect}\r\n',
                    emit('[%date% %time%] update installed'),
                ]
            else:
                lines += [
                    "set retries=0\r\n",
                    ":retry_move\r\n",
                    'set "cursize="\r\n',
                    f'for %%A in ("{new_exe_path}") do set "cursize=%%~zA"\r\n',
                    f'if not "%cursize%"=="{expected_size}" (\r\n',
                    "    set /a retries+=1\r\n",
                    emit(f'[%date% %time%] size check failed - got "%cursize%", expected {expected_size} - attempt %retries%'),
                    "    if %retries% GEQ 60 (\r\n",
                    emit('[%date% %time%] giving up - downloaded file never matched expected size, relaunching old exe'),
                    "        goto relaunch\r\n",
                    "    )\r\n",
                    "    ping -n 2 127.0.0.1 >NUL\r\n",
                    "    goto retry_move\r\n",
                    ")\r\n",
                    f'move /y "{new_exe_path}" "{current_exe}"{redirect}\r\n',
                    "if errorlevel 1 (\r\n",
                    "    set /a retries+=1\r\n",
                    emit('[%date% %time%] move failed, attempt %retries%'),
                    "    if %retries% GEQ 60 (\r\n",
                    emit('[%date% %time%] giving up on move, relaunching old exe'),
                    "        goto relaunch\r\n",
                    "    )\r\n",
                    "    ping -n 2 127.0.0.1 >NUL\r\n",
                    "    goto retry_move\r\n",
                    ")\r\n",
                    emit('[%date% %time%] move succeeded'),
                ]

            lines += [
                # Antivirus finishing its on-write scan of the
                # freshly-placed exe can still hold a lock on it for a
                # while after the swap itself completes - launching too
                # soon transiently fails with "Failed to load Python
                # DLL...LoadLibrary: The specified module could not be
                # found" even though the file itself is completely fine
                # (confirmed independently by two users: a plain manual
                # relaunch afterward works immediately). A fixed short
                # delay here wasn't always long enough - scan time varies
                # by machine - so instead of guessing, actively test for
                # the lock itself: renaming the file to its own current
                # name is a no-op that still requires the file not be
                # locked, the same trick used above for waiting on the
                # OLD install to fully release. Only on the successful-
                # swap path (falls through to here); the give-up path
                # above jumps straight to :relaunch for the untouched,
                # already-stable old install, which was never freshly
                # written and needs no settling time.
                "set settle_tries=0\r\n",
                ":settle_check\r\n",
                f'ren "{current_exe}" "{os.path.basename(current_exe)}"{redirect}\r\n',
                "if errorlevel 1 (\r\n",
                "    set /a settle_tries+=1\r\n",
                emit('[%date% %time%] exe still locked, attempt %settle_tries%'),
                "    if %settle_tries% GEQ 30 (\r\n",
                emit('[%date% %time%] giving up waiting for lock to clear, launching anyway'),
                "        goto relaunch\r\n",
                "    )\r\n",
                "    ping -n 2 127.0.0.1 >NUL\r\n",
                "    goto settle_check\r\n",
                ")\r\n",
                emit('[%date% %time%] exe no longer locked, safe to launch'),
                ":relaunch\r\n",
            ]
            # A previous fix cleared leftover _MEI* extraction folders
            # here, on the theory that PyInstaller's onefile bootloader
            # might reuse a stale, broken one instead of extracting
            # fresh. Direct evidence has since disproven that theory
            # outright: every single "Failed to load Python DLL" report
            # (across many machines and many retries on the same
            # machine) has pointed at a DIFFERENT, genuinely fresh
            # _MEI<random> folder - the bootloader never reuses one.
            # Worse, the cleanup itself was observed taking 20-100+
            # seconds (deleting a large accumulation of old folders) at
            # exactly the moment right before the critical relaunch,
            # which is exactly the kind of disk/antivirus activity burst
            # that could plausibly interfere with the NEW extraction
            # about to happen - actively making things worse rather than
            # helping. Removed rather than kept "just in case".
            # No longer auto-relaunches at all. Every attempt at fixing
            # the auto-relaunch step (settle-check timing, environment
            # sanitization, retry-with-better-detection) still hit the
            # exact same "Failed to load Python DLL" failure, on every
            # single retry, while an independent launch of the SAME exe
            # moments later (outside this batch script's own process
            # chain, e.g. a plain double-click or a fresh `Start-Process`
            # call) reliably worked - strong evidence the problem is
            # specific to being launched as a child of this exact process
            # chain, not the exe or the swap itself. Rather than keep
            # chasing that with no fix that's actually held up under
            # direct testing, the pragmatic answer is to stop trying to
            # relaunch automatically at all - the swap above still
            # happens the same as before, the user just needs to open
            # the app again themselves afterward (they're already told
            # this in the "Download and Install Update" confirmation
            # dialog before the download even starts).
            lines += [emit('[%date% %time%] update installed - please open the app again to continue')]
            if verbose:
                lines += [
                    'echo.\r\n',
                    'echo ============================================================\r\n',
                    'echo  Finished. Review the output above, then press any key to\r\n',
                    'echo  close this window.\r\n',
                    'echo ============================================================\r\n',
                    'pause >NUL\r\n',
                ]
            if is_folder:
                lines += [
                    f'rd /s /q "{staging_dir}" 2>NUL\r\n',
                    f'del /f /q "{downloaded_zip_path}" 2>NUL\r\n',
                ]
            lines += ['del "%~f0"\r\n']

            with open(bat_path, 'w') as f:
                f.write(''.join(lines))
            subprocess.Popen(['cmd', '/c', bat_path],
                             creationflags=(subprocess.CREATE_NEW_CONSOLE if verbose
                                           else subprocess.CREATE_NO_WINDOW),
                             env=_clean_relaunch_env())
            # From here on, everything happens in the batch script, a
            # separate process this log can't see into directly - non-
            # verbose mode's own copy of the same steps lands in
            # olmran_update_log.txt (same temp dir as this log file),
            # worth checking too if an update goes wrong from here.
            _debug_log(f'Finish self-update: handed off to {bat_path} '
                       f'(is_folder={is_folder}, verbose={verbose}, current_exe={current_exe}) '
                       f'- this process exits now, see olmran_update_log.txt for the batch script\'s own steps '
                       f'if not verbose')
        except Exception as e:
            _debug_log(f'Finish self-update FAILED before handoff: {e!r}\n{traceback.format_exc()}')
            self._on_update_download_failed(e)
            return
        self._save_config()
        os._exit(0)

    # ── BUILD UI ──────────────────────────────────────────────
    def _build_scrollable_root(self):
        """Wrap the whole app in a Canvas + visible vertical Scrollbar, so
        shrinking the window (or a tab just plain needing more room than
        fits on screen) never permanently hides anything below the visible
        area - it can be reached by dragging the scrollbar or scrolling the
        mouse wheel. Entirely transparent to every tab built afterward
        (they're built into self._scroll_content exactly as if it were
        `self`). The update bar (Download Page/Check for Update - see
        _build_update_bar) is ALSO built inside self._scroll_content, as
        the very first thing in it, rather than pinned above this canvas
        as separate fixed chrome - scrolling down treats it like anything
        else, scrolling it away entirely rather than permanently reserving
        blank space for it at the top of the window.

        Mouse wheel scrolling is also bound app-wide (bind_all), ONE
        single handler for the whole app's lifetime, as a convenience:
        - A widget that already handles its own wheel scrolling
          (Treeview/Text/Listbox/Combobox) is left alone rather than also
          scrolling the outer window - otherwise hovering over e.g. a
          Results table while scrolling would double-scroll both it and
          the whole window.
        - Any other scrollable tk.Canvas built elsewhere (e.g. Saved
          Builds' own canvas) registers itself in
          self._extra_scroll_canvases (see _register_scroll_canvas) so
          hovering it scrolls that canvas instead of this outer one -
          plain tk.Canvas has no built-in wheel handling of its own the
          way Treeview/Text/Listbox do, so it can't be covered by the
          class check above and needs an explicit registry instead.
          Every such canvas MUST use this registry rather than its own
          local bind_all('<MouseWheel>', ...) - a second, independent
          bind_all for the same global event replaces this one entirely
          while hovering it, and unbind_all on <Leave> then wipes it out
          for good instead of restoring it, permanently breaking the
          whole app's wheel-scroll for the rest of the session the first
          time the mouse ever crosses that widget (a real bug this
          replaced - see Saved Builds).
        The Scrollbar itself is the reliable path either way, in case
        the wheel handling ever doesn't fire for a given widget."""
        outer = ttk.Frame(self)
        outer.pack(fill='both', expand=True)

        canvas = tk.Canvas(outer, highlightthickness=0)
        vsb = ttk.Scrollbar(outer, orient='vertical', command=canvas.yview)
        canvas.configure(yscrollcommand=vsb.set)
        canvas.pack(side='left', fill='both', expand=True)
        vsb.pack(side='right', fill='y')

        content = ttk.Frame(canvas)
        content_window = canvas.create_window((0, 0), window=content, anchor='nw')

        def _on_content_configure(event):
            canvas.configure(scrollregion=canvas.bbox('all'))
        content.bind('<Configure>', _on_content_configure)

        def _on_canvas_configure(event):
            canvas.itemconfig(content_window, width=event.width)
            # content's height is otherwise purely "natural" (sum of
            # children) since only width gets synced above - meaning any
            # pack(fill='both', expand=True) deep inside a tab (e.g. the
            # Manual tab's results Treeview) never actually had extra
            # vertical space to expand into, even in a maximized window,
            # since its parent chain always stayed exactly as tall as it
            # needed to be. Stretching content to the taller of its own
            # natural height or the canvas's current viewport height (never
            # shorter, so a big tab still scrolls exactly as before) gives
            # those expand=True widgets real room to grow when the window
            # is bigger than the current tab actually needs.
            natural_height = content.winfo_reqheight()
            canvas.itemconfig(content_window, height=max(natural_height, event.height))
        canvas.bind('<Configure>', _on_canvas_configure)

        self_scrolling_classes = {'Treeview', 'Text', 'Listbox', 'TCombobox', 'ComboboxPopdownFrame'}
        self._extra_scroll_canvases = []

        def _on_global_mousewheel(event):
            delta_units = int(-1 * (event.delta / 120))
            w = event.widget
            while w is not None:
                try:
                    if w.winfo_class() in self_scrolling_classes:
                        return
                except tk.TclError:
                    break
                if w in self._extra_scroll_canvases:
                    w.yview_scroll(delta_units, 'units')
                    return
                if w is content:
                    break
                w = w.master
            canvas.yview_scroll(delta_units, 'units')

        canvas.bind_all('<MouseWheel>', _on_global_mousewheel)

        self._scroll_canvas = canvas
        self._scroll_content = content

    def _track_notebook_selected_tab_height(self, nb, margin=0, available_widget=None, track_resize=True):
        """Keeps nb sized to match only its CURRENTLY SELECTED tab's own
        required height, instead of ttk.Notebook's default of sizing to
        the largest tab across ALL of them. That default is what causes
        the app-wide "extra scrolling to reach content that's already
        on screen" symptom: a data-heavy tab (a generated report, a big
        Saved Items list) inflates every sibling tab's own effective
        height too, even while a much shorter one is actually showing -
        and since ttk.Notebook always reports that inflated size as its
        own natural request regardless of selection, it silently
        propagates upward through however many parent frames/canvases
        wrap it (see _build_scrollable_root's own <Configure> handler,
        which has no way to tell an inflated request apart from a
        genuine one). margin is subtracted from the "available" widget's
        current height before treating it as free space to grow into.

        track_resize=True (the default) additionally stretches nb to
        fill any extra space its available_widget has beyond what the
        selected tab itself needs, by also reacting to that widget's own
        <Configure>. Pass False for any notebook nested inside another
        notebook's own PAGE (i.e. nearly every nested notebook in this
        app - build_sub_notebook is the one top-level exception, parented
        directly to a plain tab frame that isn't itself managed by an
        ancestor notebook). Reason: a notebook page's own winfo_reqheight
        is still computed from its packed children as normal even though
        its ACTUAL on-screen size is separately forced by whichever
        notebook owns it - so nb.configure(height=...) here changes that
        page's reqheight, which ttk::Notebook's C-level geometry-request
        handling re-evaluates on every such change, re-firing <Configure>
        on that same page even when its final on-screen size doesn't
        actually change - which re-runs THIS function, forever (a real,
        reproduced hang - see the Item/XP/Damage/Counters notebooks after
        they were first wired up with track_resize left at its default).
        track_resize=False sidesteps this entirely by only ever reacting
        to <<NotebookTabChanged>> - it can't grow into extra window space
        this way, but that's only actually needed at the outermost level;
        every inner notebook still gets the core fix (shrinking to match
        whichever of ITS OWN tabs is selected, rather than the largest).

        available_widget (only consulted when track_resize=True) defaults
        to nb's own direct parent - correct for a notebook nested inside
        an ordinary Frame that ISN'T itself a page of another notebook
        (build_sub_notebook inside tab_build), since that Frame's own
        size never changes AS A RESULT of nb's configured height. Pass it
        explicitly for the one exception: the top-level notebook's own
        parent IS self._scroll_content, whose size DOES partly derive
        from nb's own reqheight (see _build_scrollable_root's <Configure>
        handler) - reading that same widget's height back out to decide
        nb's height would be circular. Pass self._scroll_canvas there
        instead - its own height comes from the actual window, never from
        anything inside the canvas.

        Call once, right after nb's initial tabs are added - it wires
        up <<NotebookTabChanged>> (add='+', so it never clobbers another
        handler already bound there) and keeps working for any tab added
        to nb later too. Returns the update function itself, in case a
        caller needs to run it immediately or add its own extra logic on
        top (see _on_build_subtab_changed, which also hides/shows the
        shared search buttons depending on which sub-tab is selected)."""
        def _update(event=None):
            try:
                selected = nb.nametowidget(nb.select())
            except (tk.TclError, KeyError):
                return
            selected.update_idletasks()
            if not track_resize:
                nb.configure(height=selected.winfo_reqheight())
                return
            try:
                ref = available_widget if available_widget is not None else nb.nametowidget(nb.winfo_parent())
                available = max(0, ref.winfo_height() - margin)
            except tk.TclError:
                available = 0
            nb.configure(height=max(selected.winfo_reqheight(), available))
        # add='+' - several notebooks (Counters' own sub-notebooks, etc.)
        # already bind their own <<NotebookTabChanged>> handler (e.g. for
        # border masking) before or after this call; a plain bind() would
        # silently replace whichever one was bound first instead of both
        # running.
        nb.bind('<<NotebookTabChanged>>', _update, add='+')
        if not track_resize:
            nb.after_idle(_update)
            return _update
        try:
            ref = available_widget if available_widget is not None else nb.nametowidget(nb.winfo_parent())
            ref.bind('<Configure>', _update, add='+')
        except tk.TclError:
            pass
        nb.after_idle(_update)
        return _update

    def _register_scroll_canvas(self, canvas):
        """Registers a scrollable tk.Canvas built elsewhere (e.g. Saved
        Builds) with the single app-wide mouse wheel handler set up in
        _build_scrollable_root, so hovering it scrolls that canvas
        instead of the outer window - see that method's docstring for
        why every such canvas needs to go through this rather than its
        own local bind_all('<MouseWheel>', ...)."""
        self._extra_scroll_canvases.append(canvas)

    def _build_ui(self):
        style = ttk.Style(self)
        style.theme_use('clam')
        style.configure('TNotebook.Tab', font=('Arial', 10, 'bold'), padding=[12, 6])
        style.configure('Accent.TButton', font=('Arial', 10, 'bold'))
        # Thin border around each Weapon Types/Combo's row (Weapon
        # Constraints tab) - purely visual, groups each combo's checkbox and
        # its own dropdowns together at a glance. Two shades, alternated row
        # by row (see each row's style= below) so adjacent rows are easier
        # to tell apart even though every row is otherwise the same height.
        style.configure('WeaponRow.TFrame', borderwidth=1, relief='solid', bordercolor='#888888')
        style.configure('WeaponRowAlt.TFrame', borderwidth=1, relief='solid', bordercolor='#bbbbbb')

        self._build_scrollable_root()

        nb = ttk.Notebook(self._scroll_content)
        nb.pack(fill='both', expand=True, padx=8, pady=8)

        # Built after the Notebook exists (placed overlapping its own tab
        # strip - see _build_update_bar), not pinned above it as separate
        # fixed chrome.
        self._build_update_bar(nb)

        self.tab_parse  = ttk.Frame(nb, padding=12)
        self.tab_build = ttk.Frame(nb, padding=12)
        self.tab_results = ttk.Frame(nb, padding=12)
        self.tab_saved = ttk.Frame(nb, padding=12)
        self.tab_area_items = ttk.Frame(nb, padding=12)
        self.tab_crafting = ttk.Frame(nb, padding=12)

        nb.add(self.tab_parse,  text='▶  Parse')
        nb.add(self.tab_build, text='🔨  Build')
        nb.add(self.tab_results, text='📊  Results')  # Always visible
        nb.add(self.tab_saved, text='📌  Saved Builds')  # One tab holds every save
        nb.add(self.tab_area_items, text='🗺  Area Items')
        nb.add(self.tab_crafting, text='⚒  Crafting')

        self.notebook = nb  # Store reference to notebook
        # 16 = the 8+8 padx/pady nb itself is packed with, just above.
        self._track_notebook_selected_tab_height(nb, margin=16, available_widget=self._scroll_canvas)

        self._build_parse_tab()
        self._build_fields_tab()
        self._build_export_tab()
        self._build_build_tab()
        self._build_results_tab()
        self._build_saved_builds_tab()
        self._build_area_items_tab()
        self._build_crafting_tab()

    def _build_file_list_section(self, parent, resizable=False):
        """Builds one copy of the "Load Log Files" section (toolbar +
        file table + hint) in the given parent and returns its Treeview.
        Called once per sub-tab that needs it - every copy is tracked in
        self.file_tvs/self.file_count_lbls and kept in sync by
        _refresh_file_list, so loading or removing files from any one of
        them updates them all.

        resizable=True (only the Counters sub-tab's copy uses this) adds a
        drag handle below the table - dragging it changes the table's row
        count between COUNTERS_FILE_LIST_MIN_ROWS and _MAX_ROWS (MAX is
        this same table's fixed height everywhere else), giving more or
        less room to the XP/Damage/PvP Damage notebook packed below it in
        the same parent. See _start_counters_file_resize and friends."""
        ttk.Label(parent, text="Load Log Files",
                  font=('Arial', 13, 'bold')).pack(anchor='w', pady=(0, 8))

        top = ttk.Frame(parent)
        top.pack(fill='x')
        ttk.Button(top, text="➕ Add Files",   command=self._add_files).pack(side='left', padx=(0,6))
        ttk.Button(top, text="📁 Add Folder",  command=self._add_folder).pack(side='left', padx=(0,6))
        ttk.Button(top, text="❌ Remove",      command=self._remove_files).pack(side='left', padx=(0,6))
        ttk.Button(top, text="🗑 Clear All",   command=self._clear_files).pack(side='left')
        count_lbl = ttk.Label(top, text="", foreground='#444')
        count_lbl.pack(side='right')
        self.file_count_lbls.append(count_lbl)

        cols = ('File', 'Type', 'Size')
        frame = ttk.Frame(parent)
        frame.pack(fill='both', expand=(not resizable), pady=(8, 0 if resizable else 8))

        if resizable:
            initial_rows = getattr(self, '_persisted_counters_file_rows', COUNTERS_FILE_LIST_DEFAULT_ROWS)
            initial_rows = max(COUNTERS_FILE_LIST_MIN_ROWS, min(COUNTERS_FILE_LIST_MAX_ROWS, initial_rows))
        else:
            initial_rows = COUNTERS_FILE_LIST_MAX_ROWS

        file_tv = ttk.Treeview(frame, columns=cols, show='headings', height=initial_rows)
        file_tv.heading('File', text='Filename')
        file_tv.heading('Type', text='Auto-Detected Type')
        file_tv.heading('Size', text='Size')
        file_tv.column('File', width=380)
        file_tv.column('Type', width=150)
        file_tv.column('Size', width=90, anchor='e')

        vsb = ttk.Scrollbar(frame, command=file_tv.yview)
        file_tv.configure(yscrollcommand=vsb.set)
        file_tv.pack(side='left', fill='both', expand=True)
        vsb.pack(side='right', fill='y')

        if resizable:
            self.counters_file_tv = file_tv
            self._counters_file_rows = initial_rows
            grip = ttk.Frame(parent, height=8, cursor='sb_v_double_arrow')
            grip.pack(fill='x', pady=(2, 8))
            grip_line = ttk.Separator(grip, orient='horizontal')
            grip_line.place(relx=0.5, rely=0.5, relwidth=1.0, anchor='center')
            grip_label = ttk.Label(grip, text='⋯', cursor='sb_v_double_arrow',
                                   font=('Arial', 8), foreground='#888')
            grip_label.place(relx=0.5, rely=0.5, anchor='center')
            for w in (grip, grip_line, grip_label):
                w.bind('<ButtonPress-1>', self._start_counters_file_resize)
                w.bind('<B1-Motion>', self._do_counters_file_resize)
                w.bind('<ButtonRelease-1>', self._end_counters_file_resize)

        ttk.Label(parent, text="💡 File types are auto-detected (CHAT = Chat logs, ACTION = Action logs)",
                 font=('Arial', 8, 'italic'), foreground='#666').pack(anchor='w', pady=(0,12))

        self.file_tvs.append(file_tv)
        return file_tv

    def _start_counters_file_resize(self, event):
        self._counters_resize_start_y = event.y_root
        self._counters_resize_start_rows = self._counters_file_rows

    def _do_counters_file_resize(self, event):
        if getattr(self, '_counters_resize_start_y', None) is None:
            return
        # ~20px per row is a reasonable approximation of this Treeview's
        # actual rendered row height (Arial 10 on the default ttk theme) -
        # exact precision doesn't matter since the result is clamped to
        # whole rows either way, so the drag just needs to feel roughly
        # 1:1 with the mouse.
        delta_rows = round((event.y_root - self._counters_resize_start_y) / 20)
        new_rows = self._counters_resize_start_rows + delta_rows
        new_rows = max(COUNTERS_FILE_LIST_MIN_ROWS, min(COUNTERS_FILE_LIST_MAX_ROWS, new_rows))
        if new_rows != self._counters_file_rows:
            self._counters_file_rows = new_rows
            self.counters_file_tv.configure(height=new_rows)

    def _end_counters_file_resize(self, event):
        self._counters_resize_start_y = None
        self._persisted_counters_file_rows = self._counters_file_rows
        self._save_config()

    def _mask_notebook_side_borders(self, nb):
        """Hides the left/right/bottom segments of nb's own default
        border, leaving just the top segment - it already runs the full
        width flush with the tab strip's own bottom edge, which is the
        one line worth keeping; the rest just boxes in an otherwise
        near-empty pane (the Counters sub-tab's own notebook, and each
        individual XP/Damage/PvP/Item Counter's own results notebook).
        Done by overlaying background-colored frames rather than via
        style, since ttk's Notebook.client element (clam theme) has no
        borderwidth/relief option to turn off in the first place - only
        background/bordercolor/lightcolor/darkcolor, which draw a fixed-
        width groove regardless. Call once right after creating nb (to
        mask its initial state) and bind <<NotebookTabChanged>> to this
        same method separately (see call sites) so the mask keeps up
        whenever nb goes from having no tabs at all (tab strip height 0)
        to having its first one (every tab here shares one font/padding,
        so height is otherwise the same no matter how many tabs follow).
        Deliberately does NOT bind itself - re-binding on every refresh
        would stack a duplicate callback each time instead of replacing
        it."""
        for m in getattr(nb, '_border_masks', []):
            m.destroy()
        nb.update_idletasks()
        tabs = nb.tabs()
        tab_h = nb.nametowidget(tabs[0]).winfo_y() if tabs else 0
        bg = '#dcdad5'
        bmask = tk.Frame(nb, bg=bg, height=3, bd=0, highlightthickness=0)
        bmask.place(in_=nb, x=0, rely=1.0, y=-3, relwidth=1.0, anchor='nw')
        lmask = tk.Frame(nb, bg=bg, width=3, bd=0, highlightthickness=0)
        lmask.place(in_=nb, x=0, y=tab_h, relheight=1.0, height=-tab_h, anchor='nw')
        rmask = tk.Frame(nb, bg=bg, width=3, bd=0, highlightthickness=0)
        rmask.place(in_=nb, relx=1.0, x=-3, y=tab_h, relheight=1.0, height=-tab_h, anchor='nw')
        nb._border_masks = [bmask, lmask, rmask]

    # ── PARSE TAB (FILES + PARSING) ───────────────────────────
    def _build_parse_tab(self):
        # Parse gets its own inner notebook: "Files & Search" holds
        # everything that used to live directly in this tab, and "XP
        # Counter" is a separate sub-tab, always present, clear of
        # everything else - see _build_xp_counter_subtab.
        self.parse_sub_notebook = ttk.Notebook(self.tab_parse)
        self.parse_sub_notebook.pack(fill='both', expand=True)

        t = ttk.Frame(self.parse_sub_notebook, padding=12)
        counters_tab = ttk.Frame(self.parse_sub_notebook, padding=12)
        settings_tab = ttk.Frame(self.parse_sub_notebook, padding=12)
        self.parse_sub_notebook.add(t, text='📄  Files & Search')
        self.parse_sub_notebook.add(counters_tab, text='📊  Counters')
        self.parse_sub_notebook.add(settings_tab, text='⚙  Settings')
        self._track_notebook_selected_tab_height(self.parse_sub_notebook, track_resize=False)

        # Settings sub-tab is just a mini-notebook holding Fields and
        # Export, both built by their own methods (called right after
        # _build_parse_tab in _build_ui, so self.settings_sub_notebook
        # already exists by the time they run).
        self.settings_sub_notebook = ttk.Notebook(settings_tab, style='RealmMini.TNotebook')
        self.settings_sub_notebook.pack(fill='both', expand=True)
        self._track_notebook_selected_tab_height(self.settings_sub_notebook, track_resize=False)

        # ═══ FILES SECTION ═══
        # Built via a shared helper so the exact same section (toolbar +
        # file table + hint, all backed by the one shared self.files
        # list) can appear on both this sub-tab and the Counters
        # sub-tab - loading/removing files from either place keeps both
        # in sync (see self.file_tvs / self.file_count_lbls and
        # _refresh_file_list/_remove_files).
        self.file_tvs = []
        self.file_count_lbls = []
        self.file_tv = self._build_file_list_section(t)

        # One shared "Load Log Files" section for both counters below,
        # since it's identical either way - kept in sync with Files &
        # Search's copy above (see _build_file_list_section). Resizable
        # here (unlike Files & Search's copy) so it can be shrunk to give
        # more room to the XP/Damage/PvP Damage notebook below it.
        self._build_file_list_section(counters_tab, resizable=True)

        self.counters_notebook = ttk.Notebook(counters_tab, style='RealmMini.TNotebook')
        self.counters_notebook.pack(fill='both', expand=True, pady=(10, 0))

        xp_tab = ttk.Frame(self.counters_notebook, padding=12)
        dmg_tab = ttk.Frame(self.counters_notebook, padding=12)
        pvp_dmg_tab = ttk.Frame(self.counters_notebook, padding=12)
        item_tab = ttk.Frame(self.counters_notebook, padding=12)
        self.counters_notebook.add(xp_tab, text='🧮  XP Counter')
        self.counters_notebook.add(dmg_tab, text='⚔  Damage Counter')
        self.counters_notebook.add(pvp_dmg_tab, text='🗡  PvP Damage')
        self.counters_notebook.add(item_tab, text='🎁  Item Counter')
        self._mask_notebook_side_borders(self.counters_notebook)
        self.counters_notebook.bind('<<NotebookTabChanged>>',
                                    lambda e: self._mask_notebook_side_borders(self.counters_notebook), add='+')
        self._track_notebook_selected_tab_height(self.counters_notebook, margin=10, track_resize=False)

        # ═══ SEARCH SECTION ═══
        # Search across every loaded file's actual lines - independent of Run
        # Parse, so you can e.g. find every time an item dropped across a large
        # batch of logs without parsing them all first.
        search_frame = ttk.LabelFrame(t, text="Search Logs", padding=10)
        search_frame.pack(fill='x', pady=(0,12))

        search_row = ttk.Frame(search_frame)
        search_row.pack(fill='x')
        ttk.Label(search_row, text="Find:", width=8).pack(side='left')
        self.search_query_var = tk.StringVar(value='')
        search_entry = ttk.Entry(search_row, textvariable=self.search_query_var, width=40)
        search_entry.pack(side='left', padx=4)
        search_entry.bind('<Return>', lambda e: self._search_logs())
        ttk.Button(search_row, text="🔍 Search",
                  command=self._search_logs).pack(side='left', padx=4)
        self.search_case_var = tk.BooleanVar(value=False)
        ttk.Checkbutton(search_row, text="Case sensitive",
                       variable=self.search_case_var).pack(side='left', padx=8)
        self.search_drops_only_var = tk.BooleanVar(value=True)
        ttk.Checkbutton(search_row, text="Drops only (with snapshot)",
                       variable=self.search_drops_only_var).pack(side='left', padx=8)

        ttk.Label(search_frame,
                 text="💡 \"Drops only\" catches every instance the item actually dropped (ignoring quality/material "
                      "prefixes like \"bright\" or \"glowing\", same as the Loot parser), and for each one shows a "
                      "snapshot of everything from the last timestamp through the drop line. Uncheck it to just "
                      "search every loaded file's raw text for any mention of the term.",
                 font=('Arial', 8, 'italic'), foreground='#666', wraplength=900,
                 justify='left').pack(anchor='w', pady=(4,0))

        # ═══ PVP SECTION ═══
        # Two independent searches sharing one frame: PvP Kill (left) finds
        # a player YOU killed; PvP Death (right) finds a player who killed
        # YOU. See _find_pvp_kills/_find_pvp_deaths for the exact matching
        # rules for each.
        pvp_frame = ttk.LabelFrame(t, text="PvP", padding=10)
        pvp_frame.pack(fill='x', pady=(0,12))

        pvp_kill_col = ttk.Frame(pvp_frame)
        pvp_kill_col.pack(side='left', anchor='n', fill='both', expand=True)

        ttk.Label(pvp_kill_col, text="Your Kills", font=('Arial', 9, 'bold')).pack(anchor='w', pady=(0,4))

        pvp_kill_row = ttk.Frame(pvp_kill_col)
        pvp_kill_row.pack(fill='x')
        ttk.Button(pvp_kill_row, text="⚔ Search",
                  command=self._search_pvp_kills).pack(side='left')
        # Total realm points and kill count across every match - readonly,
        # just display fields, refreshed each time this search runs (see
        # _search_pvp_kills/_find_pvp_kills).
        self.pvp_kills_rp_var = tk.StringVar(value='')
        ttk.Entry(pvp_kill_row, textvariable=self.pvp_kills_rp_var, width=6,
                 state='readonly', justify='center').pack(side='left', padx=(6,0))
        ttk.Label(pvp_kill_row, text="Total RP").pack(side='left', padx=(4,8))
        self.pvp_kills_count_var = tk.StringVar(value='')
        ttk.Entry(pvp_kill_row, textvariable=self.pvp_kills_count_var, width=6,
                 state='readonly', justify='center').pack(side='left')
        ttk.Label(pvp_kill_row, text="Kills").pack(side='left', padx=(4,0))

        pvp_death_col = ttk.Frame(pvp_frame)
        pvp_death_col.pack(side='left', anchor='n', fill='both', expand=True, padx=(20,0))

        ttk.Label(pvp_death_col, text="Your Deaths", font=('Arial', 9, 'bold')).pack(anchor='w', pady=(0,4))

        pvp_death_row = ttk.Frame(pvp_death_col)
        pvp_death_row.pack(fill='x')
        # K/D ratio - Kills / Deaths from whatever Your Kills/Your Deaths
        # have each most recently found (see _update_pvp_kd_ratio, called
        # from both _search_pvp_kills and _search_pvp_deaths so either
        # search updates it). Blank until at least one of the two has
        # actually been run.
        self.pvp_deaths_count_var = tk.StringVar(value='')
        self.pvp_kd_ratio_var = tk.StringVar(value='')
        ttk.Entry(pvp_death_row, textvariable=self.pvp_kd_ratio_var, width=6,
                 state='readonly', justify='center').pack(side='left')
        ttk.Label(pvp_death_row, text="K/D").pack(side='left', padx=(4,8))
        ttk.Button(pvp_death_row, text="💀 Search",
                  command=self._search_pvp_deaths).pack(side='left')

        pvp_participated_col = ttk.Frame(pvp_frame)
        pvp_participated_col.pack(side='left', anchor='n', fill='both', expand=True, padx=(20,0))

        ttk.Label(pvp_participated_col, text="Participated", font=('Arial', 9, 'bold')).pack(anchor='w', pady=(0,4))

        pvp_participated_row = ttk.Frame(pvp_participated_col)
        pvp_participated_row.pack(fill='x')
        ttk.Button(pvp_participated_row, text="🤝 Search",
                  command=self._search_pvp_participated).pack(side='left')
        # Same idea as the Kills row above, for the Participated search.
        self.pvp_participated_rp_var = tk.StringVar(value='')
        ttk.Entry(pvp_participated_row, textvariable=self.pvp_participated_rp_var, width=6,
                 state='readonly', justify='center').pack(side='left', padx=(6,0))
        ttk.Label(pvp_participated_row, text="Total RP").pack(side='left', padx=(4,8))
        self.pvp_participated_count_var = tk.StringVar(value='')
        ttk.Entry(pvp_participated_row, textvariable=self.pvp_participated_count_var, width=6,
                 state='readonly', justify='center').pack(side='left')
        ttk.Label(pvp_participated_row, text="Participations").pack(side='left', padx=(4,0))

        # ═══ PARSING SECTION ═══
        parse_frame = ttk.LabelFrame(t, text="Parse Options", padding=10)
        parse_frame.pack(fill='x', pady=(0,12))
        
        ttk.Label(parse_frame, text="What to Parse:", 
                 font=('Arial', 9)).pack(anchor='w', pady=(0,4))
        
        opts_frame = ttk.Frame(parse_frame)
        opts_frame.pack(anchor='w', padx=20)
        
        self.do_chat = tk.BooleanVar(value=False)
        self.do_combat = tk.BooleanVar(value=False)
        self.do_loot   = tk.BooleanVar(value=False)
        
        self.chat_cb = ttk.Checkbutton(opts_frame, text="💬 Chat", 
                                       variable=self.do_chat)
        self.chat_cb.pack(side='left', padx=(0,20))
        
        self.combat_cb = ttk.Checkbutton(opts_frame, text="⚔️ Combat", 
                                         variable=self.do_combat)
        self.combat_cb.pack(side='left', padx=(0,20))
        
        self.loot_cb = ttk.Checkbutton(opts_frame, text="💎 Loot",
                                       variable=self.do_loot)
        self.loot_cb.pack(side='left')

        ttk.Label(parse_frame, text="Counters (Run Parse also exports these if checked):",
                 font=('Arial', 9)).pack(anchor='w', pady=(8,4))

        counters_opts_frame = ttk.Frame(parse_frame)
        counters_opts_frame.pack(anchor='w', padx=20)

        # Independent of the Chat/Combat/Loot checkboxes above and their
        # auto-enable/disable logic (_update_parse_options) - these each
        # run their own full-file scan (_compute_xp_stats/
        # _compute_damage_stats/_compute_pvp_damage_stats), the same ones
        # backing the Counters sub-tab's own buttons, not gated by file
        # type the way Chat/Combat/Loot are.
        self.do_xp = tk.BooleanVar(value=False)
        self.do_damage = tk.BooleanVar(value=False)
        self.do_pvp_dealt = tk.BooleanVar(value=False)
        self.do_pvp_taken = tk.BooleanVar(value=False)

        ttk.Checkbutton(counters_opts_frame, text="🧮 XP Counter",
                       variable=self.do_xp).pack(side='left', padx=(0,20))
        ttk.Checkbutton(counters_opts_frame, text="⚔ Damage Counter",
                       variable=self.do_damage).pack(side='left', padx=(0,20))
        ttk.Checkbutton(counters_opts_frame, text="🗡 PvP Dealt",
                       variable=self.do_pvp_dealt).pack(side='left', padx=(0,20))
        ttk.Checkbutton(counters_opts_frame, text="🗡 PvP Taken",
                       variable=self.do_pvp_taken).pack(side='left')

        run_frame = ttk.Frame(t)
        run_frame.pack(pady=8)
        ttk.Button(run_frame, text="▶  Run Parse",
                   command=self._run_parse, width=22, style='Accent.TButton').pack(side='left', padx=6)
        ttk.Button(run_frame, text="👁  Snapshot: Chat",
                   command=lambda: self._show_snapshot('chat')).pack(side='left', padx=6)
        ttk.Button(run_frame, text="👁  Snapshot: Combat",
                   command=lambda: self._show_snapshot('combat')).pack(side='left', padx=6)
        ttk.Button(run_frame, text="👁  Snapshot: Loot",
                   command=lambda: self._show_snapshot('loot')).pack(side='left', padx=6)

        counters_run_frame = ttk.Frame(t)
        counters_run_frame.pack(pady=(0,8))
        ttk.Button(counters_run_frame, text="👁  Snapshot: XP",
                   command=lambda: self._show_snapshot('xp')).pack(side='left', padx=6)
        ttk.Button(counters_run_frame, text="👁  Snapshot: Damage",
                   command=lambda: self._show_snapshot('damage')).pack(side='left', padx=6)
        ttk.Button(counters_run_frame, text="👁  Snapshot: PvP Dealt",
                   command=lambda: self._show_snapshot('pvp_dealt')).pack(side='left', padx=6)
        ttk.Button(counters_run_frame, text="👁  Snapshot: PvP Taken",
                   command=lambda: self._show_snapshot('pvp_taken')).pack(side='left', padx=6)

        self.status_var = tk.StringVar(value="Load files and click 'Run Parse' to begin")
        ttk.Label(t, textvariable=self.status_var,
                  font=('Arial', 10), foreground='#222').pack(anchor='w', pady=(12,0))

        # Mini stats - Credits button shares this row, pinned to the far
        # right, rather than living inside the Parse Results box itself.
        results_row = ttk.Frame(t)
        results_row.pack(fill='x', pady=(12,0))

        self.stats_frame = ttk.LabelFrame(results_row, text="Parse Results", padding=10)
        self.stats_frame.pack(side='left')

        self.stat_labels = {}
        stat_tiles = [('chat','💬','Chat'), ('combat','⚔️','Combat'), ('loot','💎','Loot'),
                      ('xp','🧮','XP'), ('damage','⚔','Damage'),
                      ('pvp_dealt','🗡','PvP Dealt'), ('pvp_taken','🗡','PvP Taken')]
        for i, (k, icon, title) in enumerate(stat_tiles):
            f = ttk.Frame(self.stats_frame)
            f.grid(row=0, column=i, padx=20, pady=6)
            ttk.Label(f, text=f"{icon} {title}", font=('Arial', 10, 'bold')).pack()
            lbl = ttk.Label(f, text="0 rows", foreground='#555')
            lbl.pack()
            self.stat_labels[k] = lbl

        ttk.Button(results_row, text="Credits",
                  command=self._show_credits).pack(side='right', anchor='n')

        # ═══ XP COUNTER TAB (inside the Counters sub-tab, below the
        # shared "Load Log Files" section built above) ═══
        ttk.Label(xp_tab, text="XP Counter",
                  font=('Arial', 13, 'bold')).pack(anchor='w', pady=(0, 8))

        xp_top_row = ttk.Frame(xp_tab)
        xp_top_row.pack(fill='x')
        ttk.Button(xp_top_row, text="🧮 XP Counter",
                  command=self._open_xp_counter).pack(side='left')
        ttk.Label(xp_top_row,
                 text="Computes XP/hour from the loaded log(s), broken down by time actually spent in each area.",
                 font=('Arial', 8, 'italic'), foreground='#666').pack(side='left', padx=10)

        # Results notebook: an ephemeral working tab is replaced in place
        # on every click; saved reports (via that tab's own Save button)
        # get their own persistent, named tab with a Delete button,
        # restored from config below.
        self.xp_notebook = ttk.Notebook(xp_tab, style='RealmMini.TNotebook')
        self.xp_notebook.pack(fill='both', expand=True, pady=(10,0))

        self.xp_saved_reports = []
        self._xp_working_frame = None
        for rep in getattr(self, '_persisted_xp_reports', []):
            rep_name = rep.get('name', '')
            rep_data = rep.get('data', {})
            if not rep_name or not rep_data:
                continue
            frame = self._build_xp_report_frame(self.xp_notebook, rep_data, is_saved=True, name=rep_name)
            self.xp_notebook.add(frame, text=rep_name)
            self.xp_saved_reports.append({'name': rep_name, 'data': rep_data, 'frame': frame})
        self._mask_notebook_side_borders(self.xp_notebook)
        self.xp_notebook.bind('<<NotebookTabChanged>>',
                             lambda e: self._mask_notebook_side_borders(self.xp_notebook), add='+')
        self._track_notebook_selected_tab_height(self.xp_notebook, margin=10, track_resize=False)

        # ═══ DAMAGE COUNTER TAB (inside the Counters sub-tab, below the
        # shared "Load Log Files" section built above) ═══
        ttk.Label(dmg_tab, text="Damage Counter",
                  font=('Arial', 13, 'bold')).pack(anchor='w', pady=(0, 8))

        dmg_top_row = ttk.Frame(dmg_tab)
        dmg_top_row.pack(fill='x')
        ttk.Button(dmg_top_row, text="⚔ Damage Counter",
                  command=self._open_damage_counter).pack(side='left')
        ttk.Label(dmg_top_row,
                 text="Totals up damage dealt to every mob across the loaded log(s). Click any column header to sort.",
                 font=('Arial', 8, 'italic'), foreground='#666').pack(side='left', padx=10)

        self.damage_notebook = ttk.Notebook(dmg_tab, style='RealmMini.TNotebook')
        self.damage_notebook.pack(fill='both', expand=True, pady=(10,0))

        self.damage_saved_reports = []
        self._damage_working_frame = None
        for rep in getattr(self, '_persisted_damage_reports', []):
            rep_name = rep.get('name', '')
            rep_data = rep.get('data', {})
            if not rep_name or not rep_data:
                continue
            frame = self._build_damage_report_frame(self.damage_notebook, rep_data, is_saved=True, name=rep_name)
            self.damage_notebook.add(frame, text=rep_name)
            self.damage_saved_reports.append({'name': rep_name, 'data': rep_data, 'frame': frame})
        self._mask_notebook_side_borders(self.damage_notebook)
        self.damage_notebook.bind('<<NotebookTabChanged>>',
                                 lambda e: self._mask_notebook_side_borders(self.damage_notebook), add='+')
        self._track_notebook_selected_tab_height(self.damage_notebook, margin=10, track_resize=False)

        # ═══ PVP DAMAGE TAB (inside the Counters sub-tab, below the
        # shared "Load Log Files" section built above) ═══
        ttk.Label(pvp_dmg_tab, text="PvP Damage Counter",
                  font=('Arial', 13, 'bold')).pack(anchor='w', pady=(0, 8))

        pvp_dmg_top_row = ttk.Frame(pvp_dmg_tab)
        pvp_dmg_top_row.pack(fill='x')
        ttk.Button(pvp_dmg_top_row, text="🗡 PvP Damage Counter",
                  command=self._open_pvp_damage_counter).pack(side='left')
        ttk.Label(pvp_dmg_top_row,
                 text="Totals up damage dealt to and taken from other players across the loaded log(s).",
                 font=('Arial', 8, 'italic'), foreground='#666').pack(side='left', padx=10)

        self.pvp_damage_notebook = ttk.Notebook(pvp_dmg_tab, style='RealmMini.TNotebook')
        self.pvp_damage_notebook.pack(fill='both', expand=True, pady=(10,0))

        self.pvp_damage_saved_reports = []
        self._pvp_damage_working_frame = None
        for rep in getattr(self, '_persisted_pvp_damage_reports', []):
            rep_name = rep.get('name', '')
            rep_data = rep.get('data', {})
            if not rep_name or not rep_data:
                continue
            frame = self._build_pvp_damage_report_frame(
                self.pvp_damage_notebook, rep_data, is_saved=True, name=rep_name)
            self.pvp_damage_notebook.add(frame, text=rep_name)
            self.pvp_damage_saved_reports.append({'name': rep_name, 'data': rep_data, 'frame': frame})
        self._mask_notebook_side_borders(self.pvp_damage_notebook)
        self.pvp_damage_notebook.bind('<<NotebookTabChanged>>',
                                     lambda e: self._mask_notebook_side_borders(self.pvp_damage_notebook), add='+')
        self._track_notebook_selected_tab_height(self.pvp_damage_notebook, margin=10, track_resize=False)

        # ═══ ITEM COUNTER TAB (inside the Counters sub-tab, below the
        # shared "Load Log Files" section built above) ═══
        ttk.Label(item_tab, text="Item Counter",
                  font=('Arial', 13, 'bold')).pack(anchor='w', pady=(0, 8))

        item_top_row = ttk.Frame(item_tab)
        item_top_row.pack(fill='x')
        ttk.Button(item_top_row, text="🎁 Item Counter",
                  command=self._open_item_counter).pack(side='left')
        ttk.Label(item_top_row,
                 text="Drop rate of every item, per mob, across the loaded log(s) - plus a "
                      "daily/weekly/monthly/yearly breakdown when the log files' own creation dates span more than one.",
                 font=('Arial', 8, 'italic'), foreground='#666').pack(side='left', padx=10)

        item_character_row = ttk.Frame(item_tab)
        item_character_row.pack(fill='x', pady=(4,0))
        ttk.Label(item_character_row, text="Character:").pack(side='left', padx=(0,6))
        self.item_counter_character = tk.StringVar(
            value=getattr(self, '_persisted_item_counter_character', 'All Characters'))
        self.item_counter_character_combo = ttk.Combobox(
            item_character_row, textvariable=self.item_counter_character,
            values=['All Characters'], state='readonly', width=20)
        self.item_counter_character_combo.pack(side='left')
        ttk.Label(item_character_row,
                 text="💡 Extracted from each log filename's own character-name segment (e.g. "
                      "...-GNAWBIE-<timestamp>.log) - files that don't fit that pattern count as "
                      "'Unknown'. Applies the next time you click Item Counter.",
                 font=('Arial', 8, 'italic'), foreground='#666').pack(side='left', padx=10)

        item_filter_row = ttk.Frame(item_tab)
        item_filter_row.pack(fill='x', pady=(4,0))
        ttk.Label(item_filter_row, text="Show:").pack(side='left', padx=(0,6))
        self.item_counter_show_items = tk.BooleanVar(value=True)
        ttk.Checkbutton(item_filter_row, text="Items",
                       variable=self.item_counter_show_items).pack(side='left', padx=(0,12))
        self.item_counter_show_junk = tk.BooleanVar(value=False)
        ttk.Checkbutton(item_filter_row, text="Junk Loot",
                       variable=self.item_counter_show_junk).pack(side='left', padx=(0,12))
        self.item_counter_consistent = tk.BooleanVar(value=True)
        ttk.Checkbutton(item_filter_row, text="Consistent",
                       variable=self.item_counter_consistent,
                       command=self._on_item_counter_consistent_toggle).pack(side='left')
        ttk.Label(item_filter_row,
                 text="💡 Items = found in the loaded master/community database; Junk Loot = everything "
                      "else. Consistent = keep a running tally across every past click instead of "
                      "starting over from just what's currently loaded - any log file already counted "
                      "is skipped, not counted again. Applies the next time you click Item Counter.",
                 font=('Arial', 8, 'italic'), foreground='#666').pack(side='left', padx=10)

        self.item_notebook = ttk.Notebook(item_tab, style='RealmMini.TNotebook')
        self.item_notebook.pack(fill='both', expand=True, pady=(10,0))

        self.item_saved_reports = []
        self._item_working_frame = None
        for rep in getattr(self, '_persisted_item_reports', []):
            rep_name = rep.get('name', '')
            rep_data = rep.get('data', {})
            if not rep_name or not rep_data:
                continue
            frame = self._build_item_report_frame(
                self.item_notebook, rep_data, is_saved=True, name=rep_name)
            self.item_notebook.add(frame, text=rep_name)
            self.item_saved_reports.append({'name': rep_name, 'data': rep_data, 'frame': frame})
        self._mask_notebook_side_borders(self.item_notebook)
        self.item_notebook.bind('<<NotebookTabChanged>>',
                               lambda e: self._mask_notebook_side_borders(self.item_notebook), add='+')
        self._track_notebook_selected_tab_height(self.item_notebook, margin=10, track_resize=False)

        # Character dropdown needs its options populated from the
        # persisted tally BEFORE restoring the working tab below - the
        # restored selection (a past session's character, applied to the
        # StringVar's own initial value above) otherwise wouldn't be a
        # recognized option yet.
        self._refresh_item_counter_character_dropdown()

        # "Consistent" defaults to checked, and its whole point is a
        # tally that persists across sessions - so if there's already
        # one on disk, show it immediately as the working tab, without
        # waiting for files to be reloaded and the button clicked again
        # (see _open_item_counter's own silent=True handling).
        if self.item_counter_consistent.get() and self.item_consistent_tally_by_character:
            self._open_item_counter(silent=True)

    # ── FIELDS TAB ────────────────────────────────────────────
    def _build_fields_tab(self):
        # Lives inside the Settings tab's sub-notebook, alongside Export,
        # rather than as its own top-level tab.
        self.tab_fields = ttk.Frame(self.settings_sub_notebook, padding=12)
        self.settings_sub_notebook.add(self.tab_fields, text='⚙  Fields')
        t = self.tab_fields
        ttk.Label(t, text="Customize Output Columns",
                  font=('Arial', 13, 'bold')).pack(anchor='w', pady=(0,6))
        ttk.Label(t, text="Each row below is one column in the exported spreadsheet.\n"
                           "Drag rows to reorder, or use Add/Edit/Remove. Column position sets the Excel column (1=A).",
                  foreground='#444').pack(anchor='w', pady=(0,8))

        ttk.Label(t,
                 text="💡 Editing fields for types checked in Parse tab's Parse Options / Counters row",
                 font=('Arial', 9, 'italic'), foreground='#666').pack(anchor='w', pady=(0,8))

        # Create notebook for multiple field types
        self.fields_notebook = ttk.Notebook(t)
        self.fields_notebook.pack(fill='both', expand=True, pady=(0,6))

        # Create tabs for each type - order and set must match FIELD_MODES.
        self.field_frames = {}
        self.field_tvs = {}

        FIELD_MODE_LABELS = {
            'chat': '💬 Chat', 'combat': '⚔️ Combat', 'loot': '💎 Loot',
            'xp': '🧮 XP Counter', 'damage': '⚔ Damage Counter',
            'pvp_dealt': '🗡 PvP Dealt', 'pvp_taken': '🗡 PvP Taken',
        }
        for field_type in FIELD_MODES:
            frame = ttk.Frame(self.fields_notebook, padding=12)
            self.fields_notebook.add(frame, text=FIELD_MODE_LABELS[field_type])
            
            # Treeview for this type
            tree_frame = ttk.Frame(frame)
            tree_frame.pack(fill='both', expand=True, pady=(0,6))
            
            cols = ('Col #', 'Header Label', 'Data Source')
            tv = ttk.Treeview(tree_frame, columns=cols, show='headings', height=13)
            for c, w in zip(cols, [70, 220, 220]):
                tv.heading(c, text=c)
                tv.column(c, width=w)
            vsb = ttk.Scrollbar(tree_frame, command=tv.yview)
            tv.configure(yscrollcommand=vsb.set)
            tv.pack(side='left', fill='both', expand=True)
            vsb.pack(side='right', fill='y')
            
            self.field_frames[field_type] = frame
            self.field_tvs[field_type] = tv

        self._track_notebook_selected_tab_height(self.fields_notebook, margin=6, track_resize=False)

        # Buttons (work on currently visible tab)
        btns = ttk.Frame(t)
        btns.pack(anchor='w')
        ttk.Button(btns, text="➕ Add",          command=self._add_field).pack(side='left', padx=4)
        ttk.Button(btns, text="✏️ Edit",         command=self._edit_field).pack(side='left', padx=4)
        ttk.Button(btns, text="❌ Remove",       command=self._remove_field).pack(side='left', padx=4)
        ttk.Button(btns, text="⬆ Move Up",      command=self._move_up).pack(side='left', padx=4)
        ttk.Button(btns, text="⬇ Move Down",    command=self._move_down).pack(side='left', padx=4)
        ttk.Button(btns, text="🔄 Reset Defaults", command=self._reset_fields).pack(side='left', padx=4)

        self._refresh_all_fields()

